                  className={`flex-shrink-0 flex items-center gap-2 p-1.5 rounded-lg text-[10px] transition-all ${isDarkMode ? 'bg-white/5 hover:bg-white/10 text-gray-300' : 'bg-gray-100 hover:bg-gray-200 text-gray-700'}`}
