        <div className={`backdrop-blur-md border p-4 rounded-2xl shadow-2xl pointer-events-auto w-24 flex flex-col items-center justify-center gap-2 transition-all cursor-pointer relative group transform hover:scale-105 active:scale-95 h-[140px] ${themeClasses.panelBgStrong} ${isDarkMode ? 'hover:bg-gray-800' : 'hover:bg-gray-100'}`}>
           <div className={`p-2 rounded-full transition-colors ${isDarkMode ? 'bg-gray-800 text-gray-400 group-hover:bg-blue-600/20 group-hover:text-blue-400' : 'bg-gray-200 text-gray-500 group-hover:bg-blue-100 group-hover:text-blue-600'}`}>
             <UploadIcon />
