       <div 
         className={`absolute top-0 left-0 right-0 h-40 bg-[radial-gradient(circle_at_top,rgba(255,255,255,0.25)_0%,transparent_70%)] z-40 pointer-events-none flex flex-col items-center pt-8 transition-opacity duration-1000 ease-in-out ${isIntimacyVisible ? 'opacity-100' : 'opacity-0'}`}
