                 <div className="h-full bg-[#a3e635] w-[60%] shadow-[0_0_8px_rgba(163,230,53,0.6)] rounded-full"></div>
             </div>
          </div>
       </div>

       {/* Fixed Bottom Capsule Text Box - Single Line - Auto Hide */}
       <div 
         className={`absolute bottom-8 left-1/2 -translate-x-1/2 w-[70%] h-10 z-30 pointer-events-none transition-opacity duration-500 ease-in-out ${isTextBoxVisible ? 'opacity-100' : 'opacity-0'}`}
