  const [isCharging, setIsCharging] = useState(false);

  // System State
  const [brightness, setBrightness] = useState(80); // 0, 20, 40, 60, 80, 100
  const [volume, setVolume] = useState(60); // 0, 20, 40, 60, 80, 100
  const [isPowerSaving, setIsPowerSaving] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  // New States for Features
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);

  // App Feature States
  const [cheerColorIndex, setCheerColorIndex] = useState(0);
  const [isCheerStrobe, setIsCheerStrobe] = useState(false);
  const [isChatMenuOpen, setIsChatMenuOpen] = useState(false);

  const [uploadedText, setUploadedText] = useState("BBS 电子徽章");
  const [textSpeed, setTextSpeed] = useState<'slow' | 'medium' | 'fast'>('medium');
  const [textColor, setTextColor] = useState('#FFFFFF');
  const [textSize, setTextSize] = useState(2); // 1: small, 2: medium, 3: large

  const [pickupData, setPickupData] = useState<number[]>(new Array(16).fill(0));

  // Resource & Wallpaper State
  const [history, setHistory] = useState<Resource[]>([]);
  const [activeResourceId, setActiveResourceId] = useState<string | null>(null);
  const [draggedResource, setDraggedResource] = useState<Resource | null>(null);

  // AI Resources State - Changed from Array to Object Map based on Slot ID
  const [aiResources, setAiResources] = useState<Record<number, Resource>>({});
  const [activeAiResourceId, setActiveAiResourceId] = useState<string | null>(null);
  const [isAiPanelOpen, setIsAiPanelOpen] = useState(false);
  const [pendingGiftSlotId, setPendingGiftSlotId] = useState<number | null>(null);

  // Carousel State
  const [carouselEnabled, setCarouselEnabled] = useState(false);
  const [carouselSpeed, setCarouselSpeed] = useState(3);
  const [tempSpeed, setTempSpeed] = useState(3);

  // Menu Interaction State
  const [menuState, setMenuState] = useState<MenuState>('MAIN');

  // Chat State
  const [chatStatus, setChatStatus] = useState<'IDLE' | 'LISTENING' | 'SPEAKING'>('IDLE');

  // Animation State
  const [aiPreloading, setAiPreloading] = useState(false);
  const [aiExitPreloading, setAiExitPreloading] = useState(false);
  const [isFindingDevice, setIsFindingDevice] = useState(false);

  // Swipe State
  const touchStartX = useRef<number | null>(null);

  // Long press logic
  const timerRef = useRef<number | null>(null);
  const aiAnimTimerRef = useRef<number | null>(null);
  const powerTimerRef = useRef<number | null>(null);
  const isPowerLongPress = useRef(false);
  const isPowerBtnPressed = useRef(false);

  // Audio Context for Pickup
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const dataArrayRef = useRef<Uint8Array | null>(null);
  const rafIdRef = useRef<number | null>(null);

  // Initialize Gemini
  useEffect(() => {
    initChat();
  }, []);

  // Clock
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Toast Timer
  useEffect(() => {
    if (toastMessage) {
      const timer = setTimeout(() => {
        setToastMessage(null);
      }, 2000);
      return () => clearTimeout(timer);
    }
  }, [toastMessage]);

  // Power Saving Reset on Shutdown
  useEffect(() => {
    if (mode === BadgeMode.OFF) {
      setIsPowerSaving(false);
    }
  }, [mode]);

  // Carousel Logic
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (carouselEnabled && history.length > 0 && mode === BadgeMode.IDLE) {
      interval = setInterval(() => {
        setActiveResourceId(prevId => {
          const currentIndex = history.findIndex(r => r.id === prevId);
          const nextIndex = (currentIndex + 1) % history.length;
          return history[nextIndex].id;
        });
      }, carouselSpeed * 1000);
    }
    return () => clearInterval(interval);
  }, [carouselEnabled, history, carouselSpeed, mode]);

  // Reset to first AI Resource (Default / Slot 1) or Pending Gift when entering chat
  useEffect(() => {
    if (mode === BadgeMode.CHAT_ENTERING) {
      if (pendingGiftSlotId && aiResources[pendingGiftSlotId]) {
         setActiveAiResourceId(aiResources[pendingGiftSlotId].id);
         // Don't clear yet, wait for CHAT mode to consume it
      } else if (aiResources[1]) {
        setActiveAiResourceId(aiResources[1].id);
      } else {
        setActiveAiResourceId(null);
      }
    }

    // Clear pending gift when entering CHAT mode
    if (mode === BadgeMode.CHAT && pendingGiftSlotId) {
        setPendingGiftSlotId(null);
    }

    // Reset Chat Menu when entering/exiting chat
    if (mode !== BadgeMode.CHAT) {
        setIsChatMenuOpen(false);
    }
  }, [mode, aiResources, pendingGiftSlotId]);

  // Update lights based on mode and Power Saving
  // Note: Battery logic is handled in render because it needs custom hex colors
  // This effect handles system-level mode switches
  useEffect(() => {
    // If Power Saving is ON, lights are OFF regardless of other modes (except maybe boot/shutdown for feedback)
    if (isPowerSaving && mode !== BadgeMode.BOOTING && mode !== BadgeMode.SHUTTING_DOWN) {
      setLightColor(LightColor.OFF);
      return;
    }

    switch (mode) {
      case BadgeMode.OFF:
      case BadgeMode.SLEEP:
        setLightColor(LightColor.OFF);
        break;
      case BadgeMode.BOOTING:
      case BadgeMode.IDLE:
        setLightColor(LightColor.CYAN); // Default, overridden in render by battery logic
        break;
      case BadgeMode.SHUTTING_DOWN:
        setLightColor(LightColor.RED);
        break;
      case BadgeMode.MENU:
        setLightColor(LightColor.WHITE);
        break;
      case BadgeMode.CHAT:
        setLightColor(LightColor.WHITE); 
        break;
      case BadgeMode.CHAT_ENTERING:
      case BadgeMode.CHAT_EXITING:
         setLightColor(LightColor.WHITE);
         break;
    }
  }, [mode, isPowerSaving]);

  // Handle Boot and Shutdown Animation Timers
  useEffect(() => {
    if (mode === BadgeMode.BOOTING) {
      const timer = setTimeout(() => {
        setMode(BadgeMode.IDLE);
        setToastMessage("系统就绪");
      }, 4000);
      return () => clearTimeout(timer);
    }
    if (mode === BadgeMode.SHUTTING_DOWN) {
      const timer = setTimeout(() => {
        setMode(BadgeMode.OFF);
      }, 2500);
      return () => clearTimeout(timer);
    }

    // Updated Logic for AI Transition (Video vs Timer)
    if (mode === BadgeMode.CHAT_ENTERING) {
      // If we have a video resource for slot 11, don't set a timer, wait for onEnded
      if (aiResources[11]?.type === 'video') return;

      const timer = setTimeout(() => setMode(BadgeMode.CHAT), 2000);
      return () => clearTimeout(timer);
    }
    if (mode === BadgeMode.CHAT_EXITING) {
      // If we have a video resource for slot 12, don't set a timer, wait for onEnded
      if (aiResources[12]?.type === 'video') return;

      const timer = setTimeout(() => setMode(BadgeMode.IDLE), 2000);
      return () => clearTimeout(timer);
    }
  }, [mode, aiResources]); // Added aiResources to dependency

  // Pickup Audio Logic
  useEffect(() => {
    if (menuState === 'PICKUP' && mode === BadgeMode.MENU) {
      const startAudio = async () => {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
          const analyser = audioCtx.createAnalyser();
          const source = audioCtx.createMediaStreamSource(stream);

          analyser.fftSize = 64;
          source.connect(analyser);

          analyserRef.current = analyser;
          audioContextRef.current = audioCtx;
          dataArrayRef.current = new Uint8Array(analyser.frequencyBinCount);

          const update = () => {
             if (!analyserRef.current || !dataArrayRef.current) return;
             analyserRef.current.getByteFrequencyData(dataArrayRef.current);
             // Downsample to 16 bars
             const bars = [];
             const step = Math.floor(dataArrayRef.current.length / 16);
             for(let i=0; i<16; i++) {
               bars.push(dataArrayRef.current[i * step] / 255);
             }
             setPickupData(bars);
             rafIdRef.current = requestAnimationFrame(update);
          };
          update();

        } catch (e) {
          console.error("Audio pickup failed", e);
          setToastMessage("麦克风访问失败");
        }
      };
      startAudio();
    } else {
      // Cleanup
      if (rafIdRef.current) cancelAnimationFrame(rafIdRef.current);
      if (audioContextRef.current) audioContextRef.current.close();
      audioContextRef.current = null;
    }

    return () => {
      if (rafIdRef.current) cancelAnimationFrame(rafIdRef.current);
      if (audioContextRef.current) {
         audioContextRef.current.close().catch(() => {});
         audioContextRef.current = null;
      }
    };
  }, [menuState, mode]);

  // Reset menu state when exiting menu
  useEffect(() => {
    if (mode !== BadgeMode.MENU) {
      setMenuState('MAIN');
    }
  }, [mode]);

  // --- Handlers ---

  const handlePowerDown = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    isPowerBtnPressed.current = true;
    isPowerLongPress.current = false;

    powerTimerRef.current = window.setTimeout(() => {
      if (!isPowerBtnPressed.current) return;
      isPowerLongPress.current = true;
      setMode(prev => {
        if (prev === BadgeMode.OFF) return BadgeMode.BOOTING;
        else if (prev !== BadgeMode.BOOTING && prev !== BadgeMode.SHUTTING_DOWN) return BadgeMode.SHUTTING_DOWN;
        return prev;
      });
      if (navigator.vibrate) navigator.vibrate(200);
    }, 2000); 
  };

  const handlePowerUp = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    if (!isPowerBtnPressed.current) return;
    isPowerBtnPressed.current = false;

    if (powerTimerRef.current) {
      clearTimeout(powerTimerRef.current);
      powerTimerRef.current = null;
    }

    if (!isPowerLongPress.current) {
      setMode(prev => {
        if (prev === BadgeMode.OFF || prev === BadgeMode.BOOTING || prev === BadgeMode.SHUTTING_DOWN || prev === BadgeMode.CHAT_ENTERING || prev === BadgeMode.CHAT_EXITING) return prev;
        if (prev === BadgeMode.SLEEP) return BadgeMode.IDLE;
        return BadgeMode.SLEEP;
      });
    }
  };

  const handleFuncClick = () => {
    if ([BadgeMode.OFF, BadgeMode.SLEEP, BadgeMode.BOOTING, BadgeMode.SHUTTING_DOWN, BadgeMode.CHAT_ENTERING, BadgeMode.CHAT_EXITING].includes(mode)) return;

    // Toggle Chat Menu if in Chat Mode
    if (mode === BadgeMode.CHAT) {
        setIsChatMenuOpen(prev => !prev);
        return;
    }

    if (mode === BadgeMode.MENU) {
      if (menuState !== 'MAIN') {
        setMenuState('MAIN'); // Back to main menu
      } else {
        if (previousMode === BadgeMode.CHAT) {
          setMode(BadgeMode.CHAT);
          setPreviousMode(null);
        } else {
          setMode(BadgeMode.IDLE);
          setPreviousMode(null);
        }
      }
    } else {
      setPreviousMode(mode);
      setMode(BadgeMode.MENU);
    }
  };

  const startAiLongPress = () => {
    if (mode === BadgeMode.OFF || mode === BadgeMode.SLEEP || mode === BadgeMode.BOOTING || mode === BadgeMode.SHUTTING_DOWN || mode === BadgeMode.CHAT_ENTERING || mode === BadgeMode.CHAT_EXITING) return;

    // Logic when EXITING Chat (long press while in chat)
    if (mode === BadgeMode.CHAT) {
        // Wait 1 second before starting the visual effect (turning white and animating)
        aiAnimTimerRef.current = window.setTimeout(() => {
            setAiExitPreloading(true);
        }, 1000);

        // Wait 3 seconds total (1s delay + 2s animation) before actually switching mode
        timerRef.current = window.setTimeout(() => {
            setMode(BadgeMode.CHAT_EXITING);
            if (navigator.vibrate) navigator.vibrate(100);
            setAiExitPreloading(false); 
        }, 3000);
        return;
    }

    // Logic when ENTERING Chat
    aiAnimTimerRef.current = window.setTimeout(() => {
        setAiPreloading(true);
    }, 1000);

    timerRef.current = window.setTimeout(() => {
      setMode(prev => prev === BadgeMode.CHAT ? BadgeMode.CHAT_EXITING : BadgeMode.CHAT_ENTERING);
      if (navigator.vibrate) navigator.vibrate(100);
      setAiPreloading(false); // Reset animation state
    }, 3000);
  };

  const endAiLongPress = () => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
    if (aiAnimTimerRef.current) {
      clearTimeout(aiAnimTimerRef.current);
      aiAnimTimerRef.current = null;
    }
    setAiPreloading(false);
    setAiExitPreloading(false);
  };

  // Menu Logic Handlers
  const togglePowerSave = () => {
    if (!isPowerSaving) {
      setIsPowerSaving(true);
      setToastMessage("进入节能模式");
      setMode(previousMode || BadgeMode.IDLE); // Return to previous page
    } else {
      setIsPowerSaving(false);
      setToastMessage("退出节能模式");
      // Stay in menu
    }
  };

  const handleCheerClick = () => setMenuState('CHEER');
  const handleLinkClick = () => setMenuState('QRCODE');
  const handleTextClick = () => setMenuState('TEXT');
  const handlePickupClick = () => setMenuState('PICKUP');
  const handleDeleteRequest = () => setMenuState('DELETE_CONFIRM');
  const handleBrightnessClick = () => setMenuState('BRIGHTNESS');
  const handleVolumeClick = () => setMenuState('VOLUME');

  const handleGiftClick = (type: 'A_LOW' | 'A_HIGH' | 'B') => {
      const slot = type === 'B' ? 10 : 9;
      setPendingGiftSlotId(slot);
      setToastMessage(`已赠送${type === 'B' ? '专属礼物' : '礼物'}，请进入AI互动`);
  };

  const confirmDelete = () => {
    setActiveResourceId(null);
    setMenuState('MAIN');
    setToastMessage("壁纸已清除");
    setMode(BadgeMode.IDLE);
  };

  // Simulation Handlers
  const handleFindDevice = () => {
    setIsFindingDevice(true);
    if (navigator.vibrate) navigator.vibrate([500, 200, 500, 200, 500]);
    // Auto turn off after 5 seconds
    setTimeout(() => setIsFindingDevice(false), 5000);
  };

  const handleSimulateAlarm = () => {
      // Slot 14 is Alarm
      if (aiResources[14]) {
          setMode(BadgeMode.CHAT);
          setActiveAiResourceId(aiResources[14].id);
      } else {
          setToastMessage("模拟闹钟触发 (请先上传资源至 Slot 14)");
      }
  };

  const handleSimulateSchedule = () => {
      // Slot 15 is Reminder
      if (aiResources[15]) {
          setMode(BadgeMode.CHAT);
          setActiveAiResourceId(aiResources[15].id);
      } else {
          setToastMessage("模拟日程提醒 (请先上传资源至 Slot 15)");
      }
  };

  const handleSimulateMessage = () => {
      // Slot 13 is Message
      if (aiResources[13]) {
          setMode(BadgeMode.CHAT);
          setActiveAiResourceId(aiResources[13].id);
      } else {
          setToastMessage("模拟收到信息 (请先上传资源至 Slot 13)");
      }
  };

  // Helper to add resource
  const addResourceToHistory = (url: string, type: 'image' | 'video', name: string) => {
    const newResource: Resource = {
      id: Date.now().toString(),
      type,
      url,
      name
    };
    setHistory(prev => [newResource, ...prev].slice(0, 10));
    setActiveResourceId(newResource.id);
    setToastMessage("导入成功");
    if(mode === BadgeMode.SLEEP) setMode(BadgeMode.IDLE);
  };

  const handleImageGeneration = (url: string, name: string) => {
    addResourceToHistory(url, 'image', name);
    // Auto switch to idle to see the image
    setMode(BadgeMode.IDLE);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Size Limit: 50MB
    const MAX_SIZE = 50 * 1024 * 1024;
    if (file.size > MAX_SIZE) {
      setToastMessage("资源过大，请压缩至50MB内");
      return;
    }

    const isVideo = file.type.startsWith('video/');
    const url = URL.createObjectURL(file);

    if (isVideo) {
      // Check Duration via hidden video element
      const tempVideo = document.createElement('video');
      tempVideo.preload = 'metadata';
      tempVideo.onloadedmetadata = () => {
        // window.URL.revokeObjectURL(tempVideo.src); // Fix: Do not revoke URL here, needed for playback
        setToastMessage("导入成功");
        addResourceToHistory(url, 'video', file.name);
      };
      tempVideo.src = url;
    } else {
      addResourceToHistory(url, 'image', file.name);
    }
  };

  const handleAiFileUpload = (e: React.ChangeEvent<HTMLInputElement>, slotId: number) => {
      const file = e.target.files?.[0];
      if (!file) return;
      // No size limit check as requested

      const isVideo = file.type.startsWith('video/');
      const url = URL.createObjectURL(file);

      const newResource: Resource = {
        id: Date.now().toString(),
        type: isVideo ? 'video' : 'image',
        url,
        name: file.name
      };

      setAiResources(prev => ({
        ...prev,
        [slotId]: newResource
      }));

      // If we just uploaded slot 1 and no active resource is set (or chat just started), set it
      if (slotId === 1 && !activeAiResourceId) {
         setActiveAiResourceId(newResource.id);
      }
      setToastMessage(`AI 资源 ${slotId} 已添加`);
  };

  const handleAiResourceDelete = (slotId: number, e: React.MouseEvent) => {
     e.stopPropagation();
     const resource = aiResources[slotId];
     if (!resource) return;

     setAiResources(prev => {
        const next = { ...prev };
        delete next[slotId];
        return next;
     });

     if (activeAiResourceId === resource.id) {
         // Fallback to slot 1 if available
         setActiveAiResourceId(null);
     }
  };

  const handleDragStart = (e: React.DragEvent, resource: Resource) => {
    setDraggedResource(resource);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragEnd = () => setDraggedResource(null);

  const handleDropDelete = (e: React.DragEvent) => {
    e.preventDefault();
    if (draggedResource) {
      setHistory(prev => prev.filter(r => r.id !== draggedResource.id));
      if (activeResourceId === draggedResource.id) setActiveResourceId(null);
      setToastMessage("资源已删除");
      setDraggedResource(null);
    }
  };

  const handleDragOver = (e: React.DragEvent) => e.preventDefault();

  // Swipe Handlers for Cheer/Wallpaper
  const handleTouchStart = (e: React.TouchEvent | React.MouseEvent) => {
    if ((mode !== BadgeMode.IDLE && menuState !== 'CHEER') || carouselEnabled) return;
    const x = 'touches' in e ? (e as React.TouchEvent).touches[0].clientX : (e as React.MouseEvent).clientX;
    touchStartX.current = x;
  };

  const handleTouchEnd = (e: React.TouchEvent | React.MouseEvent) => {
    if (touchStartX.current === null) return;
    const x = 'changedTouches' in e ? (e as React.TouchEvent).changedTouches[0].clientX : (e as React.MouseEvent).clientX;
    const diff = touchStartX.current - x;
    touchStartX.current = null;

    if (Math.abs(diff) > 50) { 
      if (menuState === 'CHEER') {
         // Change Cheer Color
         if (diff > 0) setCheerColorIndex(prev => (prev + 1) % CHEER_COLORS.length);
         else setCheerColorIndex(prev => (prev - 1 + CHEER_COLORS.length) % CHEER_COLORS.length);
      } else if (mode === BadgeMode.IDLE && history.length > 1) {
         // Change Wallpaper
         if (diff > 0) setActiveResourceId(prevId => {
            const idx = history.findIndex(r => r.id === prevId);
            return history[(idx + 1) % history.length].id;
         });
         else setActiveResourceId(prevId => {
            const idx = history.findIndex(r => r.id === prevId);
            return history[(idx - 1 + history.length) % history.length].id;
         });
      }
    }
  };

  const activeResource = history.find(r => r.id === activeResourceId);
  // Find resource in the map by ID
  const activeAiResource = Object.values(aiResources).find(r => r.id === activeAiResourceId);

  // --- Main Render ---

  // Dynamic Light Strip Logic
  const getLightStripStyle = () => {
    // IDLE mode (not power saving) or (OFF mode AND Charging)
    if ((mode === BadgeMode.IDLE && !isPowerSaving) || ((mode === BadgeMode.OFF || mode === BadgeMode.SLEEP) && isCharging)) {
       let color = BATTERY_COLORS.HIGH;
       if (batteryLevel <= 20) color = BATTERY_COLORS.LOW;
       else if (batteryLevel <= 60) color = BATTERY_COLORS.MID;

       return { borderColor: color };
    }
    return {};
  };

  const getLightStripClass = () => {
    // Force lights off in Cheer mode
    if (mode === BadgeMode.MENU && menuState === 'CHEER') return 'opacity-0';

    // If Power Saving is ON, lights are forced OFF
    if (isPowerSaving && mode !== BadgeMode.BOOTING && mode !== BadgeMode.SHUTTING_DOWN) return 'opacity-0';

    // Shared breathing animation logic for charging states
    const chargingAnim = (isCharging && batteryLevel < 100) ? "animate-breathe-slow" : "";

    // OFF/SLEEP Mode Logic
    if (mode === BadgeMode.OFF || mode === BadgeMode.SLEEP) {
        if (isCharging) {
            // Breathing light if charging, even if off/sleep
            return `absolute inset-0 rounded-full blur-md transition-all duration-700 ease-out border-[10px] opacity-80 ${chargingAnim}`;
        }
        return 'opacity-0';
    }

    let baseClass = `absolute inset-0 rounded-full blur-md transition-all duration-700 ease-out `;

    if (mode === BadgeMode.CHAT_ENTERING) return `absolute inset-0 rounded-full blur-md opacity-100 animate-spin-once bg-[conic-gradient(from_0deg,transparent_0%,white_50%,transparent_100%)]`;
    if (mode === BadgeMode.CHAT_EXITING) return `absolute inset-0 rounded-full blur-md opacity-100 animate-spin-once bg-[conic-gradient(from_0deg,transparent_0%,#01fce9_50%,transparent_100%)]`;

    if (mode === BadgeMode.CHAT) {
       // Exit animation override
       if (aiExitPreloading) return 'opacity-0'; // Hide standard ring, use overlay

       if (chatStatus === 'LISTENING') return baseClass + `border-[10px] border-white opacity-100`;
       else if (chatStatus === 'SPEAKING') return baseClass + `border-[10px] border-white opacity-100 animate-breathe-fast`;
       return baseClass + `border-[10px] border-white opacity-60`;
    }

    // Battery Logic for IDLE mode
    if (mode === BadgeMode.IDLE) {
        return baseClass + `border-[10px] opacity-80 ${chargingAnim}`;
    }

    // Fallback for MENU and other system modes (uses lightColor state)
    const color = lightColor.replace('border-', 'border-'); 
    return baseClass + `border-[10px] ${color} opacity-80`;
  };

  // Define chargingAnim for the solid strip use as well
  const chargingAnim = (isCharging && batteryLevel < 100) ? "animate-breathe-slow" : "";

  // Helper for battery color
  const batteryInfoColor = batteryLevel <= 20 ? BATTERY_COLORS.LOW : (batteryLevel <= 60 ? BATTERY_COLORS.MID : BATTERY_COLORS.HIGH);

  // --- THEME CLASSES ---
  const themeClasses = getThemeClasses(isDarkMode);

  return (
    <div className={`min-h-screen flex items-center justify-center p-4 font-sans selection:bg-blue-500/30 overflow-hidden relative transition-colors duration-500 ${themeClasses.bg}`}>

      {/* Help Modal */}
      <HelpModal isOpen={isHelpOpen} onClose={() => setIsHelpOpen(false)} isDarkMode={isDarkMode} />

      {/* Background Ambience */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden">
        <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-gradient-to-r from-blue-900/10 to-purple-900/10 rounded-full blur-3xl transition-opacity duration-1000 ${mode === BadgeMode.OFF ? 'opacity-0' : 'opacity-100'}`}></div>
      </div>

      {/* Helper Text (Left) - Kept for quick reference */}
      <div className={`fixed top-8 left-8 text-xs space-y-2 hidden md:block font-display tracking-wide z-50 ${isDarkMode ? 'text-gray-600' : 'text-gray-400'}`}>
        <h2 className={`font-bold mb-4 border-b pb-2 ${isDarkMode ? 'text-gray-400 border-gray-800' : 'text-gray-500 border-gray-300'}`}>操作指南</h2>
        <div className="flex items-center gap-2"><span className="w-1.5 h-1.5 bg-gray-500 rounded-full"></span> 左键: 长按2秒 开/关机, 点按 亮/熄屏</div>
        <div className="flex items-center gap-2"><span className="w-1.5 h-1.5 bg-gray-500 rounded-full"></span> 右上: 长按3秒进入 AI 对话</div>
        <div className="flex items-center gap-2"><span className="w-1.5 h-1.5 bg-gray-500 rounded-full"></span> 右下: 菜单 / 返回</div>
      </div>

      {/* Top Right Controls (Theme & Help) */}
      <div className="fixed top-8 right-8 z-[55] flex items-center gap-3">
         <button 
           onClick={() => setIsDarkMode(!isDarkMode)} 
           className={`p-2 rounded-full backdrop-blur-md transition-all duration-300 border ${themeClasses.panelBgStrong} ${themeClasses.iconBase}`}
           title="切换主题"
         >
           {isDarkMode ? <SunIcon className="w-5 h-5" /> : <MoonIcon className="w-5 h-5" />}
         </button>
         <button 
           onClick={() => setIsHelpOpen(true)}
           className={`p-2 rounded-full backdrop-blur-md transition-all duration-300 border ${themeClasses.panelBgStrong} ${themeClasses.iconBase}`}
           title="使用帮助"
         >
            <HelpIcon className="w-5 h-5" />
         </button>
      </div>

      {/* View Switcher */}
      <div className={`fixed top-1/2 left-8 -translate-y-1/2 z-50 flex flex-col gap-3 backdrop-blur-md p-2 rounded-2xl border transition-colors duration-300 ${themeClasses.panelBg}`}>
         {(['LEFT', 'FRONT', 'RIGHT', 'BACK'] as ViewType[]).map((view) => (
           <button
             key={view}
             onClick={() => setCurrentView(view)}
             className={`p-2 rounded-xl transition-all duration-300 flex items-center justify-center ${currentView === view ? themeClasses.iconActive : themeClasses.iconInactive}`}
             title={VIEW_NAMES[view]}
           >
              <ViewIcon view={view} />
           </button>
         ))}
      </div>

      {/* Battery Controls (Right Side) */}
      <div className={`fixed top-1/2 right-8 -translate-y-1/2 z-50 flex flex-col gap-4 backdrop-blur-md p-3 rounded-2xl border transition-colors duration-300 ${themeClasses.panelBg}`}>

         {/* Discharging States */}
         <div className="flex flex-col gap-2">
            <span className={`text-[9px] font-bold text-center ${themeClasses.subText}`}>状态预览</span>
            {[100, 50, 20].map((level) => (
            <button
                key={level}
                onClick={() => { setBatteryLevel(level); setIsCharging(false); }}
                className={`p-2 rounded-xl transition-all duration-300 flex items-center justify-center gap-2 ${batteryLevel === level && !isCharging ? themeClasses.iconActive : themeClasses.iconInactive}`}
                title={`${level === 100 ? '高' : level === 50 ? '中' : '低'}电量`}
            >
                <BatteryLevelControl level={level} />
            </button>
            ))}
         </div>

         <div className={`h-[1px] w-full ${isDarkMode ? 'bg-gray-700/50' : 'bg-gray-300'}`}></div>

         {/* Charging States */}
         <div className="flex flex-col gap-2">
            <span className={`text-[9px] font-bold text-center ${themeClasses.subText}`}>充电模拟</span>
            {[
                { l: 100, label: '满电' },
                { l: 80, label: '高充' },
                { l: 50, label: '中充' },
                { l: 20, label: '低充' }
            ].map((item) => (
            <button
                key={`chg-${item.l}`}
                onClick={() => { setBatteryLevel(item.l); setIsCharging(true); }}
                className={`p-2 rounded-xl transition-all duration-300 flex items-center justify-center gap-2 ${batteryLevel === item.l && isCharging ? 'bg-green-600 text-white shadow-lg shadow-green-500/30' : themeClasses.iconInactive}`}
                title={item.label}
            >
                <BatteryLevelControl level={item.l} charging={true} />
            </button>
            ))}
         </div>

      </div>

      {/* Bottom Panel (Existing + New Gift Panel + New Simulation Panel) */}
      <div className="fixed bottom-24 w-full max-w-6xl px-4 z-50 flex justify-center md:justify-end gap-4 pointer-events-none">

        {/* New Simulation Panel */}
        <div className={`backdrop-blur-md border p-3 rounded-2xl shadow-2xl pointer-events-auto flex flex-col gap-2 w-40 h-[140px] transition-colors duration-300 ${themeClasses.panelBgStrong}`}>
           <div className={`text-[9px] font-bold uppercase tracking-wider ${themeClasses.subText} flex-shrink-0 flex items-center gap-2`}>
               <span className="w-1.5 h-4 bg-current rounded-sm"></span> 智能模拟
           </div>

           <div className="flex flex-col gap-1.5 flex-1 overflow-y-auto no-scrollbar">
               <button 
                  onClick={handleSimulateSchedule}
                  className={`flex-shrink-0 flex items-center gap-2 p-1.5 rounded-lg text-[10px] transition-all ${isDarkMode ? 'bg-white/5 hover:bg-white/10 text-gray-300' : 'bg-gray-100 hover:bg-gray-200 text-gray-700'}`}
               >
                   <CalendarIcon className="w-3.5 h-3.5"/> 日程提醒 (Slot 15)
               </button>
               <button 
                  onClick={handleSimulateAlarm}
                  className={`flex-shrink-0 flex items-center gap-2 p-1.5 rounded-lg text-[10px] transition-all ${isDarkMode ? 'bg-white/5 hover:bg-white/10 text-gray-300' : 'bg-gray-100 hover:bg-gray-200 text-gray-700'}`}
               >
                   <ClockIcon className="w-3.5 h-3.5"/> 闹钟触发 (Slot 14)
               </button>
               <button 
                  onClick={handleSimulateMessage}
                  className={`flex-shrink-0 flex items-center gap-2 p-1.5 rounded-lg text-[10px] transition-all ${isDarkMode ? 'bg-white/5 hover:bg-white/10 text-gray-300' : 'bg-gray-100 hover:bg-gray-200 text-gray-700'}`}
               >
                   <MessageSquareIcon className="w-3.5 h-3.5"/> 收到信息 (Slot 13)
               </button>
           </div>
        </div>

        {/* New Gift Panel */}
        <div className={`backdrop-blur-md border p-3 rounded-2xl shadow-2xl pointer-events-auto flex flex-col gap-2 w-36 h-[140px] transition-colors duration-300 ${themeClasses.panelBgStrong}`}>
           <div className={`text-[9px] font-bold uppercase tracking-wider ${themeClasses.subText} flex items-center gap-2`}>
               <GiftIcon className="w-3 h-3"/> 送礼物
           </div>

           <div className="flex flex-col gap-1.5 flex-1 justify-center">
               <button 
                  onClick={() => handleGiftClick('A_LOW')}
                  className={`flex items-center gap-2 p-1.5 rounded-lg text-[10px] transition-all ${isDarkMode ? 'bg-white/5 hover:bg-white/10 text-gray-300' : 'bg-gray-100 hover:bg-gray-200 text-gray-700'}`}
               >
                   <span className="w-1.5 h-1.5 rounded-full bg-blue-400"></span> 低价礼物A
               </button>
               <button 
                  onClick={() => handleGiftClick('A_HIGH')}
                  className={`flex items-center gap-2 p-1.5 rounded-lg text-[10px] transition-all ${isDarkMode ? 'bg-white/5 hover:bg-white/10 text-gray-300' : 'bg-gray-100 hover:bg-gray-200 text-gray-700'}`}
               >
                   <span className="w-1.5 h-1.5 rounded-full bg-purple-400"></span> 高价礼物A
               </button>
               <button 
                  onClick={() => handleGiftClick('B')}
                  className={`flex items-center gap-2 p-1.5 rounded-lg text-[10px] transition-all border border-yellow-500/30 ${isDarkMode ? 'bg-yellow-500/10 hover:bg-yellow-500/20 text-yellow-500' : 'bg-yellow-50 hover:bg-yellow-100 text-yellow-600'}`}
               >
                   <span className="w-1.5 h-1.5 rounded-full bg-yellow-400"></span> 专属礼物B
               </button>
           </div>
        </div>

        {/* Text Upload Control */}
        <div className={`backdrop-blur-md border p-4 rounded-2xl shadow-2xl pointer-events-auto flex flex-col gap-2 w-48 h-[140px] transition-colors duration-300 ${themeClasses.panelBgStrong}`}>
           <div className={`text-[9px] font-bold uppercase tracking-wider ${themeClasses.subText}`}>系统 & 文字</div>
           <input 
             type="text" 
             value={uploadedText} 
             onChange={(e) => setUploadedText(e.target.value)} 
             className={`border rounded text-xs px-2 py-1 w-full outline-none focus:border-blue-500 ${isDarkMode ? 'bg-black/50 border-gray-600 text-white' : 'bg-gray-100 border-gray-300 text-gray-800'}`}
             placeholder="输入滚动文字..."
           />
           <div className="flex gap-2 justify-between">
              <select 
                className={`text-[9px] border rounded px-1 ${isDarkMode ? 'bg-black/50 text-white border-gray-600' : 'bg-gray-100 text-gray-800 border-gray-300'}`} 
                value={textSpeed} 
                onChange={(e) => setTextSpeed(e.target.value as any)}
              >
                 <option value="slow">慢</option>
                 <option value={1}>小</option>
                 <option value={2}>中</option>
                 <option value={3}>大</option>
              </select>
           </div>

           <button onClick={() => { setMenuState('TEXT'); if(mode !== BadgeMode.MENU) handleFuncClick(); }} className="mt-auto bg-blue-600/80 hover:bg-blue-600 text-white text-[10px] py-1 rounded transition">
             预览文字
           </button>
        </div>

        <div className={`backdrop-blur-md border p-4 rounded-2xl shadow-2xl pointer-events-auto flex gap-4 animate-fadeIn transform transition-all hover:scale-105 h-[140px] ${themeClasses.panelBgStrong}`}>
          <div className={`flex flex-col gap-2 border-r pr-4 min-w-[100px] justify-center ${isDarkMode ? 'border-gray-700/50' : 'border-gray-300'}`}>
             <div className={`text-[9px] font-bold mb-1 uppercase tracking-wider ${themeClasses.subText}`}>播放设置</div>
             <div className="flex items-center gap-2">
               <input 
                 type="number" 
                 min="1" 
                 max="30" 
                 value={tempSpeed} 
                 onChange={(e) => setTempSpeed(Math.max(1, Math.min(30, parseInt(e.target.value) || 1)))}
                 className={`w-12 border rounded px-1 text-xs text-center py-1 outline-none focus:border-blue-500 ${isDarkMode ? 'bg-black/50 border-gray-600 text-white' : 'bg-gray-100 border-gray-300 text-gray-800'}`}
               />
               <span className={`text-[9px] ${themeClasses.subText}`}>秒</span>
             </div>
             <button 
               onClick={() => {
                 setCarouselSpeed(tempSpeed);
                 setCarouselEnabled(!carouselEnabled);
                 setToastMessage(carouselEnabled ? "轮播已关闭" : `轮播开启: ${tempSpeed}秒`);
               }}
               className={`text-[9px] py-1.5 px-2 rounded-md flex items-center justify-center gap-1 transition-colors font-medium ${carouselEnabled ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20' : (isDarkMode ? 'bg-gray-800 text-gray-300 hover:bg-gray-700' : 'bg-gray-200 text-gray-700 hover:bg-gray-300')}`}
             >
               {carouselEnabled ? <PauseIcon/> : <PlayIcon/>}
               {carouselEnabled ? '暂停' : '开始'}
             </button>
          </div>

          <div className="flex flex-col min-w-[200px]">
            <div className={`text-[9px] font-bold mb-2 uppercase tracking-wider flex justify-between ${themeClasses.subText}`}>
              <span>图库 ({history.length}/10)</span>
              <span className={`font-normal ${isDarkMode ? 'text-gray-600' : 'text-gray-400'}`}>拖拽移出以删除</span>
            </div>
            {history.length === 0 ? (
               <div className={`h-16 flex items-center justify-center text-[10px] italic rounded-lg border border-dashed ${isDarkMode ? 'bg-black/20 text-gray-600 border-gray-700/30' : 'bg-gray-100 text-gray-400 border-gray-300'}`}>
                 暂无媒体文件
               </div>
            ) : (
               <div className="flex gap-2 overflow-x-auto no-scrollbar max-w-[400px] pb-1">
                 {history.map((res) => (
                   <div 
                     key={res.id}
                     className={`relative group flex-shrink-0 w-16 h-16 rounded-lg overflow-hidden cursor-pointer border transition-all shadow-md ${activeResourceId === res.id ? 'border-blue-500 ring-2 ring-blue-500/20' : (isDarkMode ? 'border-gray-700 hover:border-gray-500' : 'border-gray-300 hover:border-gray-400')}`}
                     onClick={() => {
                       setActiveResourceId(res.id);
                       setCarouselEnabled(false); 
                     }}
                     draggable
                     onDragStart={(e) => handleDragStart(e, res)}
                     onDragEnd={handleDragEnd}
                   >
                     {res.type === 'video' ? (
                       <video src={res.url} muted className="w-full h-full object-cover" />
                     ) : (
                       <img src={res.url} alt="thumbnail" className="w-full h-full object-cover" />
                     )}
                     {res.type === 'video' && <div className="absolute inset-0 flex items-center justify-center bg-black/20"><div className="w-4 h-4 text-white opacity-80"><PlayIcon /></div></div>}
                   </div>
                 ))}
               </div>
            )}
          </div>
        </div>

