                <div className="flex-shrink-0 w-16 h-16 rounded-2xl bg-gradient-to-br from-yellow-300 to-orange-500 shadow-lg shadow-orange-500/30 flex items-center justify-center text-3xl snap-center border-2 border-white/40 transform scale-110">
                    <div className="relative">
                        ❤️
                        <div className="absolute -bottom-1 -right-1 text-base">🔒</div>
                    </div>
                </div>
                <div className="flex-shrink-0 w-12 h-12 rounded-full bg-gradient-to-br from-pink-400 to-rose-600 shadow-lg shadow-pink-500/30 flex items-center justify-center text-xl snap-center border-2 border-white/20 transform hover:scale-110 transition-transform">
                    🎲
