                 <div className="flex-shrink-0 w-12 h-12 rounded-full bg-gradient-to-br from-green-400 to-emerald-600 shadow-lg shadow-green-500/30 flex items-center justify-center text-xl snap-center border-2 border-white/20 transform hover:scale-110 transition-transform">
