   const handleMenuScroll = () => {
       if (!menuScrollRef.current) return;
       const container = menuScrollRef.current;
       const center = container.scrollLeft + (container.clientWidth / 2);

       const children = Array.from(container.children);
       let closest = 0;
       let minDist = Infinity;

       children.forEach((child, index) => {
           const childEl = child as HTMLElement;
           const childCenter = childEl.offsetLeft + (childEl.clientWidth / 2);
           const dist = Math.abs(center - childCenter);
           if (dist < minDist) {
               minDist = dist;
               closest = index;
           }
       });

       if (closest !== activeMenuIndex) {
           setActiveMenuIndex(closest);
       }
   };

   // Auto scroll to middle item (Index 2) when menu opens
   useEffect(() => {
       if (isMenuOpen && menuScrollRef.current) {
           const container = menuScrollRef.current;
           const children = container.children;
           if (children[2]) {
               const child = children[2] as HTMLElement;
               const scrollPos = child.offsetLeft - (container.clientWidth / 2) + (child.clientWidth / 2);
               // Use setTimeout to ensure layout is ready
               setTimeout(() => {
                  container.scrollTo({ left: scrollPos, behavior: 'smooth' });
               }, 100);
           }
       }
   }, [isMenuOpen]);

   // Check if Gift (Slot 9 or 10) is currently playing
   const isGiftPlaying = (aiResources[9] && activeAiResourceId === aiResources[9].id) ||
                         (aiResources[10] && activeAiResourceId === aiResources[10].id);

   // Keep a ref for callbacks
   const isGiftPlayingRef = useRef(isGiftPlaying);
   useEffect(() => {
       isGiftPlayingRef.current = isGiftPlaying;
   }, [isGiftPlaying]);

   // Sync chatStatus to ref for use in closures/callbacks
   useEffect(() => {
     chatStatusRef.current = chatStatus;
   }, [chatStatus]);

   // Keep pomodoro status in ref for AI context
   const pomodoroStatusRef = useRef(pomodoroStatus);
   useEffect(() => {
       pomodoroStatusRef.current = pomodoroStatus;
   }, [pomodoroStatus]);

   // Reset idle timer function
   const resetIdleTimer = () => {
      if (idleTimerRef.current) clearTimeout(idleTimerRef.current);

      // Only set idle timer if we are in Default state (Slot 1) and not speaking/action
      // AND not in Pomodoro mode
      if (activeAiResourceId === aiResources[1]?.id && chatStatusRef.current !== 'SPEAKING' && pomodoroStatusRef.current === 'IDLE') {
          idleTimerRef.current = window.setTimeout(() => {
              if (isMountedRef.current && aiResources[16]) {
                  setActiveAiResourceId(aiResources[16].id);
              }
          }, 10000);
      }
   };

   // Monitor active resource and status for idle logic
   useEffect(() => {
       resetIdleTimer();
       return () => {
           if (idleTimerRef.current) clearTimeout(idleTimerRef.current);
       };
   }, [activeAiResourceId, chatStatus, aiResources, pomodoroStatus]);

   const startListening = () => {
     const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
     if (!SpeechRecognition) return;
     const recognition = new SpeechRecognition();
     recognition.lang = 'zh-CN';
     recognition.continuous = false; 
     recognition.interimResults = false;
     recognition.onstart = () => {
       if (isMountedRef.current) setChatStatus('LISTENING');
     };
     recognition.onend = () => {
       // Only restart if mounted, not speaking, AND NOT PLAYING GIFT
       if (isMountedRef.current && chatStatusRef.current !== 'SPEAKING' && !isGiftPlayingRef.current) {
         try { recognition.start(); } catch(e){}
       }
     };
     recognition.onresult = async (event: any) => {
       // Ignore result if gift is playing
       if (isGiftPlayingRef.current) return;

       const transcript = event.results[0][0].transcript;
       if (transcript.includes("关闭") || transcript.includes("退出")) {
          setMode(BadgeMode.CHAT_EXITING);
          return;
       }

       // Show Text Box when user speaks
       setIsTextBoxVisible(true);
       setChatStatus('SPEAKING');
       setDisplayText("...");

       // Inject Context if in Pomodoro Mode
       let messageToSend = transcript;
       if (pomodoroStatusRef.current === 'FOCUS') {
           messageToSend = `[系统提示: 用户当前正在专注模式，还剩${Math.ceil(timeLeft/60)}分钟。请务必用可爱严厉的语气催促用户专心工作/学习，拒绝闲聊，除非用户询问时间。] ${transcript}`;
       }

       const stream = sendMessageStream(messageToSend, handleToolCall);
       let rawText = "";
       let detectedSlotId = 8; // Default to Normal (8)
       let tagChecked = false;

       try {
         for await (const chunk of stream) {
           rawText += chunk;

           // Check for tag in the beginning
           if (!tagChecked) {
             const match = rawText.match(/^\[(开心|生气|困惑|悲伤|平常)\]/);
             if (match) {
               const emotion = match[1];
               if (emotion === '开心') detectedSlotId = 4;
               else if (emotion === '生气') detectedSlotId = 5;
               else if (emotion === '困惑') detectedSlotId = 6;
               else if (emotion === '悲伤') detectedSlotId = 7;
               else detectedSlotId = 8;
               tagChecked = true;
             } else if (rawText.length > 5 && !rawText.trim().startsWith('[')) {
               tagChecked = true; 
             }
           }

           // Remove tag for display
           const textToShow = rawText.replace(/^\[(开心|生气|困惑|悲伤|平常)\]/, '');
           if (isMountedRef.current) setDisplayText(textToShow);
         }
       } catch(e) {
         let fallbackText = "我好像掉线了...";
         if (isMountedRef.current) setDisplayText(fallbackText);
       }

       const finalText = rawText.replace(/^\[(开心|生气|困惑|悲伤|平常)\]/, '');
       speak(finalText, detectedSlotId);
     };
     recognitionRef.current = recognition;
     try { recognition.start(); } catch(e) { console.error(e); }
   };

   // Handle Gift/Listening State Logic
   useEffect(() => {
     isMountedRef.current = true;

     if (isGiftPlaying) {
         // Stop listening if gift is playing
         if (recognitionRef.current) recognitionRef.current.stop();
         setChatStatus('IDLE');
         setDisplayText("✨ 收到礼物啦 ✨");
         setIsTextBoxVisible(true); // Show text box for gift message
     } else {
         // Start listening if not gift playing
         // But only if we are not currently speaking (though normally we wouldn't be if we just finished a gift)
         setChatStatus('LISTENING');
         startListening();
     }

     return () => {
       isMountedRef.current = false;
       if (recognitionRef.current) recognitionRef.current.stop();
       if (synthRef.current) synthRef.current.cancel();
       if (idleTimerRef.current) clearTimeout(idleTimerRef.current);
     };
   }, [isGiftPlaying]); // Re-run when gift status changes

   const handleToolCall = async (name: string, args: any): Promise<string> => {
       // Tool functionality removed
       return "功能已禁用";
   };

   const speak = (text: string, emotionSlotId: number = 8) => {
     const synth = synthRef.current;
     synth.cancel();
     const utterance = new SpeechSynthesisUtterance(text);
     let zhVoice = synth.getVoices().find(v => (v.lang === 'zh-CN' || v.lang === 'zh-TW') && (v.name.includes('Google') || v.name.includes('Female')));
     if (!zhVoice) zhVoice = synth.getVoices().find(v => v.lang.includes('zh'));
     if (zhVoice) utterance.voice = zhVoice;

     // Optimized for a more natural, cute female voice
     utterance.rate = 1.1; 
     utterance.pitch = 1.3;

     utterance.volume = volume / 100;
     utterance.onstart = () => {
       if (isMountedRef.current) {
           setChatStatus('SPEAKING');
           setIsTextBoxVisible(true); // Ensure visible when AI starts speaking

           // Determine Active Resource based on Pomodoro State first
           if (pomodoroStatusRef.current === 'FOCUS' && aiResources[17]) {
               setActiveAiResourceId(aiResources[17].id);
           } else if (pomodoroStatusRef.current === 'BREAK' && aiResources[18]) {
               setActiveAiResourceId(aiResources[18].id);
           } else {
               // Normal Emotion Logic
               if (aiResources[emotionSlotId]) {
                   setActiveAiResourceId(aiResources[emotionSlotId].id);
               } else if (aiResources[8]) {
                   setActiveAiResourceId(aiResources[8].id);
               } else if (aiResources[1]) {
                   setActiveAiResourceId(aiResources[1].id);
               }
           }
       }
     };
     utterance.onend = () => {
       if (isMountedRef.current) {
          setChatStatus('LISTENING');

          // Revert Resource Logic
          if (pomodoroStatusRef.current === 'FOCUS' && aiResources[17]) {
               setActiveAiResourceId(aiResources[17].id);
          } else if (pomodoroStatusRef.current === 'BREAK' && aiResources[18]) {
               setActiveAiResourceId(aiResources[18].id);
          } else if (aiResources[1]) {
               setActiveAiResourceId(aiResources[1].id);
          }

          if (recognitionRef.current) try { recognitionRef.current.start(); } catch(e){}

          // Auto hide text box 1 second after speaking finishes
          setTimeout(() => {
              if (isMountedRef.current) setIsTextBoxVisible(false);
          }, 1000);
       }
     };
     synth.speak(utterance);
   };

   // Logic for Actions and Idle
   // Slot 1: Default
   // Slot 2: Head Pat (Swipe)
   // Slot 3: Poke Face (Click)
   // Slot 8: Speaking (Normal)
   // Slot 4-7: Emotions
   // Slot 9: Gift A (Low/High)
   // Slot 10: Gift B (Exclusive)
   // Slot 16: Bored (Idle)
   // Slot 17: Focus
   // Slot 18: Break

   // Check if current resource is an Action (play once)
   const isActionResource = 
        (aiResources[2] && backgroundResource?.id === aiResources[2].id) || 
        (aiResources[3] && backgroundResource?.id === aiResources[3].id) ||
        (aiResources[9] && backgroundResource?.id === aiResources[9].id) ||
        (aiResources[10] && backgroundResource?.id === aiResources[10].id) ||
        (aiResources[16] && backgroundResource?.id === aiResources[16].id);

   // Check if current resource is the Speaking loop (Slots 4-8)
   const isSpeakingResource = 
       (aiResources[8] && backgroundResource?.id === aiResources[8].id) ||
       (aiResources[4] && backgroundResource?.id === aiResources[4].id) ||
       (aiResources[5] && backgroundResource?.id === aiResources[5].id) ||
       (aiResources[6] && backgroundResource?.id === aiResources[6].id) ||
       (aiResources[7] && backgroundResource?.id === aiResources[7].id);

   // Check if current resource is Default loop (Slot 1)
   const isDefaultResource = aiResources[1] && backgroundResource?.id === aiResources[1].id;

   // Check if Pomodoro Loop
   const isPomodoroResource = 
       (aiResources[17] && backgroundResource?.id === aiResources[17].id) ||
       (aiResources[18] && backgroundResource?.id === aiResources[18].id);

   // Should loop if Default or Speaking or Pomodoro
   const shouldLoop = isDefaultResource || isSpeakingResource || isPomodoroResource;

   // Auto-revert for Image Actions (Action resources that are images need to manually revert to default after a timeout)
   useEffect(() => {
     if (isActionResource && backgroundResource?.type === 'image') {
       const timer = setTimeout(() => {
         if (isMountedRef.current) {
             if (pomodoroStatusRef.current === 'FOCUS' && aiResources[17]) setActiveAiResourceId(aiResources[17].id);
             else if (pomodoroStatusRef.current === 'BREAK' && aiResources[18]) setActiveAiResourceId(aiResources[18].id);
             else if (aiResources[1]) setActiveAiResourceId(aiResources[1].id);
         }
       }, 4000); // Display static action images for 4 seconds before reverting
       return () => clearTimeout(timer);
     }
   }, [activeAiResourceId, isActionResource, backgroundResource, aiResources]);

   const handleTouchStart = (e: React.TouchEvent | React.MouseEvent) => {
     const x = 'touches' in e ? (e as React.TouchEvent).touches[0].clientX : (e as React.MouseEvent).clientX;
     chatTouchStartX.current = x;
     resetIdleTimer(); // User interaction resets idle timer
   };

   const handleTouchEnd = (e: React.TouchEvent | React.MouseEvent) => {
     if (chatTouchStartX.current === null) return;
     const x = 'changedTouches' in e ? (e as React.TouchEvent).changedTouches[0].clientX : (e as React.MouseEvent).clientX;
     const diff = chatTouchStartX.current - x;
     chatTouchStartX.current = null;
     resetIdleTimer(); // User interaction resets idle timer

     // Trigger Swipe (Head Pat - Slot 2) if distance > 30px
     if (Math.abs(diff) > 30) {
        if (aiResources[2]) {
           setActiveAiResourceId(aiResources[2].id);
        }
     } 
     // Trigger Click (Poke Face - Slot 3) if distance < 5px (basically a tap)
     else if (Math.abs(diff) < 5) {
        if (aiResources[3]) {
            setActiveAiResourceId(aiResources[3].id);
        }
     }
   };

   // Determine if Intimacy should be visible
   // Only show intimacy if NOT in Pomodoro Mode
   const showIntimacy = (isIntimacyVisible || isMenuOpen) && pomodoroStatus === 'IDLE';

   // Determine if Pomodoro Top Bar should be visible
   const showPomodoroTop = pomodoroStatus === 'FOCUS' || pomodoroStatus === 'BREAK';

   return (
     <div 
       className="w-full h-full bg-[#1a1a2e] flex flex-col relative overflow-hidden z-20 select-none"
       onTouchStart={handleTouchStart}
       onTouchEnd={handleTouchEnd}
       onMouseDown={handleTouchStart}
       onMouseUp={handleTouchEnd}
       onMouseLeave={() => { chatTouchStartX.current = null; }}
     >
       <div className="absolute inset-0 z-0">
          <SeamlessBackground 
             resource={backgroundResource}
             shouldLoop={!!shouldLoop} // Ensure boolean
             volume={volume}
             onEnded={() => {
                 // Logic to revert to default if needed
                 if (isActionResource) {
                     if (pomodoroStatusRef.current === 'FOCUS' && aiResources[17]) setActiveAiResourceId(aiResources[17].id);
                     else if (pomodoroStatusRef.current === 'BREAK' && aiResources[18]) setActiveAiResourceId(aiResources[18].id);
                     else if (aiResources[1]) setActiveAiResourceId(aiResources[1].id);
                 }
             }}
          />
       </div>

       <style>{`
         @keyframes vertical-scroll {
           0% { transform: translateY(100%); opacity: 0; }
           5% { transform: translateY(0%); opacity: 1; }
           95% { transform: translateY(0%); opacity: 1; }
           100% { transform: translateY(-100%); opacity: 0; }
         }
         .animate-vertical-scroll {
            animation: vertical-scroll 8s linear infinite;
         }
       `}</style>

       {/* Intimacy Indicator Overlay */}
       <div 
         className={`absolute top-0 left-0 right-0 h-48 bg-[radial-gradient(circle_at_top,rgba(0,0,0,0.9)_0%,transparent_70%)] z-40 pointer-events-none flex flex-col items-center pt-[10px] transition-opacity duration-500 ease-in-out ${showIntimacy ? 'opacity-100' : 'opacity-0'}`}
       >
          <div className="flex flex-col items-center gap-2 transform scale-110">
             <div className="flex items-center gap-2">
                 <div className="relative">
                    <HeartIcon className="w-8 h-8 text-[#a3e635]" />
                    <span className="absolute inset-0 flex items-center justify-center text-xs font-bold text-black/60 pt-[1px]">6</span>
                 </div>
                 <span className="text-white font-display font-bold text-base tracking-widest drop-shadow-md">亲密</span>
             </div>
             {/* Progress Bar */}
             <div className="w-28 h-2 bg-gray-700/50 backdrop-blur-sm rounded-full overflow-hidden border border-white/10">
                 <div className="h-full bg-[#a3e635] w-[60%] shadow-[0_0_8px_rgba(163,230,53,0.6)] rounded-full"></div>
             </div>
          </div>
       </div>

       {/* Pomodoro Top Bar */}
       <div 
         className={`absolute top-0 left-0 right-0 h-40 bg-[radial-gradient(circle_at_top,rgba(0,0,0,0.9)_0%,transparent_70%)] z-40 pointer-events-none flex flex-col items-center pt-2 transition-opacity duration-500 ease-in-out ${showPomodoroTop ? 'opacity-100' : 'opacity-0'}`}
       >
          <div className="flex flex-col items-center gap-1">
             <div className={`text-xs font-bold px-3 py-1 rounded-full backdrop-blur-md border border-white/20 shadow-lg ${pomodoroStatus === 'FOCUS' ? 'bg-blue-600/60 text-blue-100' : 'bg-orange-600/60 text-orange-100'}`}>
                 {pomodoroStatus === 'FOCUS' ? '专注中' : '休息中'}
             </div>
             <div className="font-display font-bold text-2xl text-white tracking-widest drop-shadow-[0_0_10px_rgba(255,255,255,0.5)]">
                 {formatTime(timeLeft)}
             </div>
          </div>
       </div>

       {/* Pomodoro Stop Button (Bottom) */}
       {showPomodoroTop && (
           <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-50 animate-fadeIn">
               <button 
                  onClick={() => setPomodoroStatus('CONFIRM_STOP')}
                  className="bg-red-500/80 hover:bg-red-600 backdrop-blur-md text-white text-xs font-bold px-6 py-2 rounded-full border border-white/20 shadow-lg active:scale-95 transition-all"
               >
                   停止专注
               </button>
           </div>
       )}

       {/* Pomodoro Settings Modal */}
       {pomodoroStatus === 'SETTINGS' && (
           <div className="absolute inset-0 z-[60] bg-black/80 backdrop-blur-md flex flex-col items-center justify-center p-6 animate-fadeIn">
               <h3 className="text-white font-display text-xl font-bold mb-6">番茄钟设置</h3>

               <div className="w-full space-y-4 mb-8">
                   <div className="flex flex-col gap-2">
                       <label className="text-blue-300 text-xs font-bold uppercase">专注时长 (分钟)</label>
                       <div className="flex items-center justify-between bg-white/10 rounded-xl p-2">
                           <button onClick={() => setFocusLength(Math.max(5, focusLength - 5))} className="w-8 h-8 rounded-lg bg-white/10 hover:bg-white/20 text-white flex items-center justify-center">-</button>
                           <span className="text-xl font-bold font-display">{focusLength}</span>
                           <button onClick={() => setFocusLength(Math.min(60, focusLength + 5))} className="w-8 h-8 rounded-lg bg-white/10 hover:bg-white/20 text-white flex items-center justify-center">+</button>
                       </div>
                   </div>

                   <div className="flex flex-col gap-2">
                       <label className="text-orange-300 text-xs font-bold uppercase">休息时长 (分钟)</label>
                       <div className="flex items-center justify-between bg-white/10 rounded-xl p-2">
                           <button onClick={() => setBreakLength(Math.max(1, breakLength - 1))} className="w-8 h-8 rounded-lg bg-white/10 hover:bg-white/20 text-white flex items-center justify-center">-</button>
                           <span className="text-xl font-bold font-display">{breakLength}</span>
                           <button onClick={() => setBreakLength(Math.min(15, breakLength + 1))} className="w-8 h-8 rounded-lg bg-white/10 hover:bg-white/20 text-white flex items-center justify-center">+</button>
                       </div>
                   </div>
               </div>

               <div className="flex gap-4 w-full">
                   <button onClick={() => setPomodoroStatus('IDLE')} className="flex-1 bg-gray-700 hover:bg-gray-600 text-white py-3 rounded-xl font-bold">取消</button>
                   <button onClick={startPomodoro} className="flex-1 bg-blue-600 hover:bg-blue-500 text-white py-3 rounded-xl font-bold shadow-lg shadow-blue-500/30">开始</button>
               </div>
           </div>
       )}

       {/* Confirm Stop Modal */}
       {pomodoroStatus === 'CONFIRM_STOP' && (
           <div className="absolute inset-0 z-[70] bg-black/90 backdrop-blur-md flex flex-col items-center justify-center p-6 animate-fadeIn">
                <div className="text-white font-bold text-lg mb-2">确定退出专注吗？</div>
                <div className="text-gray-400 text-xs mb-6 text-center">虽然 AI 会有点失望，<br/>但休息一下也没关系哦。</div>
                <div className="flex gap-4 w-full">
                   <button onClick={() => setPomodoroStatus(timeLeft > 0 ? (aiResources[17] && activeAiResourceId === aiResources[17].id ? 'FOCUS' : 'BREAK') : 'FOCUS')} className="flex-1 bg-gray-700 hover:bg-gray-600 text-white py-3 rounded-xl font-bold">继续专注</button>
                   <button onClick={stopPomodoro} className="flex-1 bg-red-600 hover:bg-red-500 text-white py-3 rounded-xl font-bold shadow-lg shadow-red-500/30">退出</button>
               </div>
           </div>
       )}

       {/* Bottom Slide-up Menu */}
       <div className={`absolute bottom-0 left-0 right-0 h-32 bg-gradient-to-t from-black/90 via-black/50 to-transparent z-40 transition-transform duration-500 ease-out flex items-center ${isMenuOpen && pomodoroStatus === 'IDLE' ? 'translate-y-0' : 'translate-y-full'}`}>
           <div 
             ref={menuScrollRef}
             onScroll={handleMenuScroll}
             className="w-full flex items-center overflow-x-auto no-scrollbar snap-x gap-6 py-4 px-[calc(50%-24px)]"
           >
                {menuItems.map((item, index) => {
                    const isActive = index === activeMenuIndex;
                    return (
                        <div 
                            key={item.id} 
                            onClick={item.onClick}
                            className={`
                                flex-shrink-0 rounded-full bg-gradient-to-br ${item.color} ${item.shadow} shadow-lg
                                flex items-center justify-center snap-center border-2 border-white/20 transform transition-all duration-300 ease-out cursor-pointer
                                ${isActive ? 'w-16 h-16 border-white/60 scale-110 z-10 opacity-100' : 'w-12 h-12 scale-90 opacity-60'}
                            `}
                        >
                            <div className={`${isActive ? 'text-3xl' : 'text-xl'} transition-all duration-300`}>
                                {item.content}
                            </div>
                        </div>
                    );
                })}
           </div>
       </div>

       {/* Fixed Bottom Capsule Text Box - Single Line - Auto Hide */}
       <div 
         className={`absolute bottom-8 left-1/2 -translate-x-1/2 w-[70%] h-10 z-30 pointer-events-none transition-opacity duration-500 ease-in-out ${isTextBoxVisible && !isMenuOpen ? 'opacity-100' : 'opacity-0'}`}
       >
          {/* Black Liquid Glass Effect Box - Capsule Shape */}
          <div className="relative w-full h-full bg-black/60 backdrop-blur-md rounded-full border border-white/20 shadow-lg flex flex-col items-center justify-center overflow-hidden">

             {/* Scrolling Text Container - Fixed Height for One Line */}
             <div className="w-full h-full flex items-center justify-center relative px-3">
                 <div className="absolute w-full animate-vertical-scroll flex items-center justify-center">
                    <p className="text-white/95 text-[10px] font-medium text-center leading-normal drop-shadow-md font-sans tracking-wide whitespace-pre-wrap">
                        {displayText}
                    </p>
                 </div>
             </div>
          </div>
       </div>
     </div>
   );
};

