// --- Chat Component ---
const ChatComp = ({ 
  volume, 
  setMode, 
  setChatStatus, 
  chatStatus,
  backgroundResource,
  onGenerateImage,
  aiResources,
  activeAiResourceId,
  setActiveAiResourceId,
