      if (activeAiResourceId === aiResources[1]?.id && chatStatusRef.current !== 'SPEAKING' && pomodoroStatusRef.current === 'IDLE' && whiteNoiseStatusRef.current === 'IDLE' && divinationStatusRef.current === 'IDLE') {
