                    <XIcon className="w-5 h-5" />
                </button>

               {/* Entities Layer */}
               {ranchEntities.map(entity => (
                   <div 
                       key={entity.id}
                       className="absolute transition-transform cursor-pointer hover:scale-110 active:scale-95"
                       style={{ 
                           left: `${entity.x}%`, 
                           top: `${entity.y}%`,
                           width: `${entity.size}%`,
                           height: `${entity.size}%`,
