   // Reset idle timer function
   const resetIdleTimer = () => {
      if (idleTimerRef.current) clearTimeout(idleTimerRef.current);

      // Only set idle timer if we are in Default state (Slot 1) and not speaking/action
      // AND not in Pomodoro mode
      // AND not in White Noise mode
      // AND not in Divination mode
      // AND not in Ranch mode
      if (activeAiResourceId === aiResources[1]?.id && chatStatusRef.current !== 'SPEAKING' && pomodoroStatusRef.current === 'IDLE' && whiteNoiseStatusRef.current === 'IDLE' && divinationStatusRef.current === 'IDLE' && ranchStatusRef.current === 'IDLE') {
