       if (synthRef.current) synthRef.current.cancel();
       if (idleTimerRef.current) clearTimeout(idleTimerRef.current);
       startNewSession();
     };
   }, [isMicDisabledResource]);

   const handleToolCall = async (name: string, args: any): Promise<string> => { return "功能已禁用"; };

   const activeBackgroundResource = ranchStatus === 'ACTIVE' && aiResources[40] ? aiResources[40] : backgroundResource;
   const isActionResource = (aiResources[2] && backgroundResource?.id === aiResources[2].id) || (aiResources[3] && backgroundResource?.id === aiResources[3].id) || (aiResources[9] && backgroundResource?.id === aiResources[9].id) || (aiResources[10] && backgroundResource?.id === aiResources[10].id) || (aiResources[16] && backgroundResource?.id === aiResources[16].id);
