       if(toastMessage) {
           const t = setTimeout(() => setToastMessage(null), 2000);
           return () => clearTimeout(t);
       }
   }, [toastMessage]);

   const exitRanch = () => {
       setRanchStatus('IDLE');
       onCloseMenu();
   };

   const openEntityDetail = (entity: RanchEntity) => {
       setSelectedEntity(entity);
       setRanchStatus('DETAIL');
   };

   const closeRanchDetail = () => {
       setRanchStatus('ACTIVE');
       setSelectedEntity(null);
   };

   // Pomodoro Logic
   useEffect(() => {
       if (pomodoroStatus === 'FOCUS' || pomodoroStatus === 'BREAK') {
           timerIntervalRef.current = window.setInterval(() => {
               setTimeLeft(prev => {
                   if (prev <= 0) {
                       if (pomodoroStatus === 'FOCUS') {
                           setPomodoroStatus('BREAK');
                           setTimeLeft(breakLength * 60);
                           if (aiResources[18]) setActiveAiResourceId(aiResources[18].id);
                       } else {
                           setPomodoroStatus('FOCUS');
                           setTimeLeft(focusLength * 60);
                           if (aiResources[17]) setActiveAiResourceId(aiResources[17].id);
                       }
                       return 0;
                   }
                   return prev - 1;
               });
           }, 1000);
       } else {
           if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
       }
       return () => {
           if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
       };
   }, [pomodoroStatus, focusLength, breakLength, aiResources]);

   const startPomodoro = () => {
       setPomodoroStatus('FOCUS');
       setTimeLeft(focusLength * 60);
       if (aiResources[17]) setActiveAiResourceId(aiResources[17].id);
   };

   const stopPomodoro = () => {
       setPomodoroStatus('IDLE');
       onCloseMenu();
       if (aiResources[1]) setActiveAiResourceId(aiResources[1].id);
   };

   // White Noise Logic
   const exitWhiteNoise = () => {
       setWhiteNoiseStatus('IDLE');
       onCloseMenu();
       if (aiResources[1]) setActiveAiResourceId(aiResources[1].id);
   };

   // Divination Logic
   const stopDivination = () => {
       setDivinationStatus('IDLE');
       onCloseMenu();
       if (aiResources[1]) setActiveAiResourceId(aiResources[1].id);
       startNewSession();
   };

   useEffect(() => {
       setLocalVolume(volume);
   }, [volume]);

   // Menu Logic Refs
   const menuScrollRef = useRef<HTMLDivElement>(null);
   const [activeMenuIndex, setActiveMenuIndex] = useState(2); 

   const menuItems = [
     { id: 'rocket', content: '🚀', color: 'from-blue-400 to-blue-600', shadow: 'shadow-blue-500/30', onClick: startRanch },
     { id: 'heart', content: '🔮', color: 'from-purple-500 to-indigo-600', shadow: 'shadow-purple-500/30', onClick: startDivination },
     { id: 'dice', content: '🎲', color: 'from-pink-400 to-rose-600', shadow: 'shadow-pink-500/30', onClick: startPomodoroSettings },
     { id: 'candy', content: '🍬', color: 'from-green-400 to-emerald-600', shadow: 'shadow-green-500/30', onClick: startWhiteNoise },
     { id: 'pill', content: '💊', color: 'from-purple-400 to-indigo-600', shadow: 'shadow-purple-500/30', onClick: () => {} },
   ];

   // Intimacy & Greeting Timer
   useEffect(() => {
     setTimeout(() => { if (isMountedRef.current) setIsIntimacyVisible(false); }, 3000);
     setIsTextBoxVisible(true);
     setTimeout(() => { if (isMountedRef.current) setIsTextBoxVisible(false); }, 3000); 
   }, []);

   const handleMenuScroll = () => {
       if (!menuScrollRef.current) return;
       const container = menuScrollRef.current;
       const center = container.scrollLeft + (container.clientWidth / 2);
       const children = Array.from(container.children);
       let closest = 0;
       let minDist = Infinity;
       children.forEach((child, index) => {
           const childEl = child as HTMLElement;
           const dist = Math.abs(center - (childEl.offsetLeft + (childEl.clientWidth / 2)));
           if (dist < minDist) { minDist = dist; closest = index; }
       });
       if (closest !== activeMenuIndex) setActiveMenuIndex(closest);
   };

   useEffect(() => {
       if (isMenuOpen && menuScrollRef.current) {
           const container = menuScrollRef.current;
           setTimeout(() => {
              if (container.children[2]) {
                  const child = container.children[2] as HTMLElement;
                  const scrollPos = child.offsetLeft - (container.clientWidth / 2) + (child.clientWidth / 2);
                  container.scrollTo({ left: scrollPos, behavior: 'smooth' });
              }
           }, 100);
       }
   }, [isMenuOpen]);

   // Disable mic when specific resources are playing to prevent self-triggering
   const isMicDisabledResource = (aiResources[2] && activeAiResourceId === aiResources[2].id) || // Head Pat
                                 (aiResources[3] && activeAiResourceId === aiResources[3].id) || // Poke Face
                                 (aiResources[9] && activeAiResourceId === aiResources[9].id) || // Gift A
                                 (aiResources[10] && activeAiResourceId === aiResources[10].id) || // Gift B
                                 (aiResources[11] && activeAiResourceId === aiResources[11].id) || // Entrance
                                 (aiResources[12] && activeAiResourceId === aiResources[12].id);   // Exit

   const isMicDisabledResourceRef = useRef(isMicDisabledResource);
   useEffect(() => { isMicDisabledResourceRef.current = isMicDisabledResource; }, [isMicDisabledResource]);
   useEffect(() => { chatStatusRef.current = chatStatus; }, [chatStatus]);

   const resetIdleTimer = () => {
      if (idleTimerRef.current) clearTimeout(idleTimerRef.current);
      if (activeAiResourceId === aiResources[1]?.id && chatStatusRef.current !== 'SPEAKING' && pomodoroStatusRef.current === 'IDLE' && whiteNoiseStatusRef.current === 'IDLE' && divinationStatusRef.current === 'IDLE' && ranchStatusRef.current === 'IDLE') {
          idleTimerRef.current = window.setTimeout(() => {
              if (isMountedRef.current && aiResources[16]) setActiveAiResourceId(aiResources[16].id);
          }, 10000);
      }
   };

   useEffect(() => {
       resetIdleTimer();
       return () => { if (idleTimerRef.current) clearTimeout(idleTimerRef.current); };
   }, [activeAiResourceId, chatStatus, aiResources, pomodoroStatus, whiteNoiseStatus, divinationStatus, ranchStatus]);

   const speak = (text: string, slotId: number) => {
       if (!synthRef.current) return;
       synthRef.current.cancel();

       if (aiResources[slotId]) {
           setActiveAiResourceId(aiResources[slotId].id);
       }

       const utterance = new SpeechSynthesisUtterance(text);
       utterance.lang = 'zh-CN';

       const voices = synthRef.current.getVoices();
       const zhVoice = voices.find(v => v.lang === 'zh-CN') || voices.find(v => v.lang.includes('zh'));
       if (zhVoice) utterance.voice = zhVoice;

       // Set Speed and Pitch
       utterance.rate = 1.1; 
       utterance.pitch = 1.3; 

       utterance.onstart = () => {
           setChatStatus('SPEAKING');
           // Force stop recognition to prevent self-hearing
           if (recognitionRef.current) {
                try { recognitionRef.current.stop(); } catch(e) {}
           }
           if (idleTimerRef.current) clearTimeout(idleTimerRef.current);
       };

       utterance.onend = () => {
           if (!isMountedRef.current) return;
           setChatStatus('LISTENING');

           if (pomodoroStatusRef.current === 'FOCUS' && aiResources[17]) {
                setActiveAiResourceId(aiResources[17].id);
           } else if (pomodoroStatusRef.current === 'BREAK' && aiResources[18]) {
                setActiveAiResourceId(aiResources[18].id);
           } else if (whiteNoiseStatusRef.current !== 'IDLE' && aiResources[19]) {
                setActiveAiResourceId(aiResources[19].id);
           } else if (divinationStatusRef.current !== 'IDLE' && aiResources[21]) {
                setActiveAiResourceId(aiResources[21].id);
           } else if (aiResources[1]) {
                setActiveAiResourceId(aiResources[1].id);
           }

           // Only restart if no special resource is blocking mic
           if (recognitionRef.current && !isMicDisabledResourceRef.current) {
                try { recognitionRef.current.start(); } catch(e) {}
           }

           resetIdleTimer();
       };

       utterance.onerror = (e) => {
           console.error("Speech error:", e);
           if (!isMountedRef.current) return;
           setChatStatus('LISTENING');
           if (aiResources[1]) setActiveAiResourceId(aiResources[1].id);
           if (!isMicDisabledResourceRef.current) {
                try { recognitionRef.current.start(); } catch(e) {}
           }
       };

       synthRef.current.speak(utterance);
   };

   const startListening = () => {
     const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
     if (!SpeechRecognition) return;
     const recognition = new SpeechRecognition();
     recognition.lang = 'zh-CN';
     recognition.continuous = false; 
     recognition.interimResults = false;
     recognition.onstart = () => { if (isMountedRef.current) setChatStatus('LISTENING'); };
     recognition.onend = () => {
       if (isMountedRef.current && chatStatusRef.current !== 'SPEAKING' && !isMicDisabledResourceRef.current) {
         try { recognition.start(); } catch(e){}
       }
     };
     recognition.onresult = async (event: any) => {
       if (isMicDisabledResourceRef.current) return;
       const transcript = event.results[0][0].transcript;
       if (transcript.includes("关闭") || transcript.includes("退出")) {
          setMode(BadgeMode.CHAT_EXITING);
          return;
       }
       setIsTextBoxVisible(true);
       setChatStatus('SPEAKING');
       setDisplayText("...");

       // --- Voice Command Checks ---
       if (transcript.includes("占卜") || transcript.includes("算命") || transcript.includes("运势")) {
           speak("收到，正在启动量子占卜程序...", 8);
           setTimeout(startDivination, 2000);
           return;
       }
       if (transcript.includes("白噪音") || transcript.includes("助眠") || transcript.includes("下雨") || transcript.includes("海浪")) {
           speak("好的，让我们放松一下。", 8);
           setTimeout(startWhiteNoise, 2000);
           return;
       }
       if (transcript.includes("番茄钟") || transcript.includes("专注") || transcript.includes("工作") || (transcript.includes("学习") && !transcript.includes("什么"))) {
           speak("要开始专注了吗？加油哦！", 8);
           setTimeout(startPomodoroSettings, 2000);
           return;
       }
       if (transcript.includes("牧场") || transcript.includes("农场") || transcript.includes("宠物")) {
           speak("正在前往数据牧场...", 8);
           setTimeout(startRanch, 2000);
           return;
       }

       let messageToSend = transcript;
       if (pomodoroStatusRef.current === 'FOCUS') {
           messageToSend = `[系统提示: 用户当前正在专注模式，还剩${Math.ceil(timeLeft/60)}分钟。请务必用可爱严厉的语气催促用户专心工作/学习，拒绝闲聊，除非用户询问时间。] ${transcript}`;
       } else if (divinationStatusRef.current !== 'IDLE') {
           const currentStep = divinationStepRef.current;
           const limit = divinationRoundLimitRef.current;
           const target = targetFortuneRef.current;
           if (currentStep < limit) {
               messageToSend = `[系统提示: 身份：赛博世界科学占卜师。当前阶段：数据采集（第${currentStep + 1}/${limit}轮）。目标运势（保密）：${target}。请根据用户刚才的回答，生成下一个关联性强的数据采集问题。追问方向可以涉及：生物节律、近期社交图谱、潜意识碎片或义体兼容性。语气保持冷静、精密。切记：不要揭示运势。] 用户输入: ${transcript}`;
               divinationStepRef.current += 1;
               setDivinationStep(prev => prev + 1);
           } else {
               messageToSend = `[系统提示: 身份：赛博世界科学占卜师。当前阶段：运算完成，输出报告。目标运势：${target}。请生成一份详尽的“未来概率预测报告”。要求：1. 篇幅要长，分析要全面。2. 必须引用用户在之前问询环节提供的具体回答（如提到过的睡眠、饮食或心情等）作为数据支撑，以增加“科学算命”的可信度。3. 使用大量赛博朋克术语（如：概率云坍缩、因果律算法、量子纠缠）。4. 最终结论归结为【${target}】，并给出建议。] 用户输入: ${transcript}`;
               divinationStepRef.current += 1; 
           }
       } else {
           setChatRoundCount(prev => prev + 1);
       }

       const stream = sendMessageStream(messageToSend, handleToolCall);
       let rawText = "";
       let detectedSlotId = 8;
       let tagChecked = false;
       let detectedEmotion = '';

       try {
         for await (const chunk of stream) {
           rawText += chunk;
           if (!tagChecked) {
             const match = rawText.match(/^\[(开心|生气|困惑|悲伤|平常)\]/);
             if (match) {
               const emotion = match[1];
               detectedEmotion = emotion;
               if (emotion === '开心') detectedSlotId = 4;
               else if (emotion === '生气') detectedSlotId = 5;
               else if (emotion === '困惑') detectedSlotId = 6;
               else if (emotion === '悲伤') detectedSlotId = 7;
               else detectedSlotId = 8;
               tagChecked = true;
             } else if (rawText.length > 5 && !rawText.trim().startsWith('[')) {
               tagChecked = true; 
             }
           }
           if (isMountedRef.current) setDisplayText(rawText.replace(/^\[(开心|生气|困惑|悲伤|平常)\]/, ''));
         }
       } catch(e) {
         if (isMountedRef.current) setDisplayText("我好像掉线了...");
       }

       const finalText = rawText.replace(/^\[(开心|生气|困惑|悲伤|平常)\]/, '');
       speak(finalText, detectedSlotId);
       if (detectedEmotion) spawnEntityFromEmotion(detectedEmotion);
     };
     recognitionRef.current = recognition;
     try { recognition.start(); } catch(e) { console.error(e); }
   };

   useEffect(() => {
     isMountedRef.current = true;
     if (isMicDisabledResource) {
         if (recognitionRef.current) recognitionRef.current.stop();
         setChatStatus('IDLE');
         // Only show text box if it's a gift (slot 9 or 10)
         if ((aiResources[9] && activeAiResourceId === aiResources[9].id) || (aiResources[10] && activeAiResourceId === aiResources[10].id)) {
            setDisplayText("✨ 收到礼物啦 ✨");
            setIsTextBoxVisible(true);
         }
     } else {
         setChatStatus('LISTENING');
         startListening();
     }
     return () => {
       isMountedRef.current = false;
       if (recognitionRef.current) recognitionRef.current.stop();
       if (synthRef.current) synthRef.current.cancel();
       if (idleTimerRef.current) clearTimeout(idleTimerRef.current);
       startNewSession();
     };
   }, [isMicDisabledResource]);

   const handleToolCall = async (name: string, args: any): Promise<string> => { return "功能已禁用"; };

   const activeBackgroundResource = ranchStatus === 'ACTIVE' && aiResources[40] ? aiResources[40] : backgroundResource;
   const isActionResource = (aiResources[2] && backgroundResource?.id === aiResources[2].id) || 
                            (aiResources[3] && backgroundResource?.id === aiResources[3].id) || 
                            (aiResources[9] && backgroundResource?.id === aiResources[9].id) || 
                            (aiResources[10] && backgroundResource?.id === aiResources[10].id) || 
                            (aiResources[16] && backgroundResource?.id === aiResources[16].id) ||
                            (aiResources[23] && backgroundResource?.id === aiResources[23].id) || // NFC 1
                            (aiResources[24] && backgroundResource?.id === aiResources[24].id);    // NFC 2
   const isSpeakingResource = (aiResources[8] && backgroundResource?.id === aiResources[8].id) || (aiResources[4] && backgroundResource?.id === aiResources[4].id) || (aiResources[5] && backgroundResource?.id === aiResources[5].id) || (aiResources[6] && backgroundResource?.id === aiResources[6].id) || (aiResources[7] && backgroundResource?.id === aiResources[7].id);
   const isDefaultResource = aiResources[1] && backgroundResource?.id === aiResources[1].id;
   const isPomodoroResource = (aiResources[17] && backgroundResource?.id === aiResources[17].id) || (aiResources[18] && backgroundResource?.id === aiResources[18].id);
   const isWhiteNoiseResource = aiResources[19] && backgroundResource?.id === aiResources[19].id;
   const isDivinationLoop = (aiResources[21] && backgroundResource?.id === aiResources[21].id) || (aiResources[22] && backgroundResource?.id === aiResources[22].id);
   const shouldLoop = isDefaultResource || isSpeakingResource || isPomodoroResource || isWhiteNoiseResource || isDivinationLoop;

   useEffect(() => {
     if (isActionResource && backgroundResource?.type === 'image') {
       const timer = setTimeout(() => {
         if (isMountedRef.current) {
             if (pomodoroStatusRef.current === 'FOCUS' && aiResources[17]) setActiveAiResourceId(aiResources[17].id);
             else if (pomodoroStatusRef.current === 'BREAK' && aiResources[18]) setActiveAiResourceId(aiResources[18].id);
             else if (whiteNoiseStatusRef.current !== 'IDLE' && aiResources[19]) setActiveAiResourceId(aiResources[19].id);
             else if (divinationStatusRef.current !== 'IDLE' && aiResources[21]) setActiveAiResourceId(aiResources[21].id);
             else if (aiResources[1]) setActiveAiResourceId(aiResources[1].id);
         }
       }, 4000); 
       return () => clearTimeout(timer);
     }
   }, [activeAiResourceId, isActionResource, backgroundResource, aiResources]);

   const handleTouchStart = (e: React.TouchEvent | React.MouseEvent) => {
     const x = 'touches' in e ? (e as React.TouchEvent).touches[0].clientX : (e as React.MouseEvent).clientX;
     chatTouchStartX.current = x;
     resetIdleTimer();
   };

   const handleTouchEnd = (e: React.TouchEvent | React.MouseEvent) => {
     if (chatTouchStartX.current === null) return;
     const x = 'changedTouches' in e ? (e as React.TouchEvent).changedTouches[0].clientX : (e as React.MouseEvent).clientX;
     const diff = chatTouchStartX.current - x;
     chatTouchStartX.current = null;
     resetIdleTimer();
     if (Math.abs(diff) > 30) { if (aiResources[2]) setActiveAiResourceId(aiResources[2].id); } 
     else if (Math.abs(diff) < 5) { if (aiResources[3]) setActiveAiResourceId(aiResources[3].id); }
   };

   const showIntimacy = (isIntimacyVisible || isMenuOpen) && pomodoroStatus === 'IDLE' && whiteNoiseStatus === 'IDLE' && divinationStatus === 'IDLE' && ranchStatus === 'IDLE';

   return (
     <div 
       className="w-full h-full bg-[#1a1a2e] flex flex-col relative overflow-hidden z-20 select-none"
       onTouchStart={handleTouchStart}
       onTouchEnd={handleTouchEnd}
       onMouseDown={handleTouchStart}
       onMouseUp={handleTouchEnd}
       onMouseLeave={() => { chatTouchStartX.current = null; }}
     >
       <div className="absolute inset-0 z-0">
          <SeamlessBackground 
             resource={activeBackgroundResource}
             shouldLoop={!!shouldLoop} 
             volume={volume} 
             onEnded={() => {
                 if (divinationStatusRef.current === 'INTRO' && aiResources[20] && backgroundResource?.id === aiResources[20].id) {
                     setDivinationStatus('WAITING');
                     if (aiResources[21]) setActiveAiResourceId(aiResources[21].id);
                     return;
                 }
                 if (isActionResource) {
                     if (pomodoroStatusRef.current === 'FOCUS' && aiResources[17]) setActiveAiResourceId(aiResources[17].id);
                     else if (pomodoroStatusRef.current === 'BREAK' && aiResources[18]) setActiveAiResourceId(aiResources[18].id);
                     else if (whiteNoiseStatusRef.current !== 'IDLE' && aiResources[19]) setActiveAiResourceId(aiResources[19].id);
                     else if (divinationStatusRef.current !== 'IDLE' && aiResources[21]) setActiveAiResourceId(aiResources[21].id);
                     else if (aiResources[1]) setActiveAiResourceId(aiResources[1].id);
                 }
             }}
          />
       </div>

       <div 
         className={`absolute top-0 left-0 right-0 h-48 bg-[radial-gradient(circle_at_top,rgba(0,0,0,0.9)_0%,transparent_70%)] z-40 pointer-events-none flex flex-col items-center pt-[10px] transition-opacity duration-500 ease-in-out ${showIntimacy ? 'opacity-100' : 'opacity-0'}`}
       >
          <div className="flex flex-col items-center gap-2 transform scale-110">
             <div className="flex items-center gap-2">
                 <div className="relative"><HeartIcon className="w-8 h-8 text-[#a3e635]" /><span className="absolute inset-0 flex items-center justify-center text-xs font-bold text-black/60 pt-[1px]">6</span></div>
                 <span className="text-white font-display font-bold text-base tracking-widest drop-shadow-md">亲密</span>
             </div>
             <div className="w-28 h-2 bg-gray-700/50 backdrop-blur-sm rounded-full overflow-hidden border border-white/10"><div className="h-full bg-[#a3e635] w-[60%] shadow-[0_0_8px_rgba(163,230,53,0.6)] rounded-full"></div></div>
          </div>
       </div>

       <div 
         className={`absolute top-0 left-0 right-0 h-48 bg-[radial-gradient(circle_at_top,rgba(255,215,0,0.2)_0%,transparent_70%)] z-40 pointer-events-none flex flex-col items-center pt-[10px] transition-opacity duration-500 ease-in-out ${showGoldHeader ? 'opacity-100' : 'opacity-0'}`}
       >
          <div className="flex flex-col items-center gap-2 transform scale-110">
             <div className="flex items-center gap-2"><div className="text-2xl">🪙</div><span className="text-yellow-400 font-display font-bold text-xl tracking-widest drop-shadow-md">{goldCount}</span></div>
          </div>
       </div>

       {toastMessage && (
           <div className="absolute top-20 left-1/2 -translate-x-1/2 bg-gray-900/90 text-white text-[10px] px-3 py-1.5 rounded-full border border-gray-700 shadow-xl z-[80] whitespace-nowrap animate-slideDown backdrop-blur-md">{toastMessage}</div>
       )}

       <RanchComp 
            status={ranchStatus} 
            chatRoundCount={chatRoundCount}
            entities={ranchEntities}
            coins={coins}
            floatingTexts={floatingTexts}
            selectedEntity={selectedEntity}
            onCollectCoin={collectCoin}
            onOpenDetail={openEntityDetail}
            onCloseDetail={closeRanchDetail}
            onExit={exitRanch}
       />

       <PomodoroComp 
            status={pomodoroStatus}
            focusLength={focusLength}
            breakLength={breakLength}
            setFocusLength={setFocusLength}
            setBreakLength={setBreakLength}
            onStart={startPomodoro}
            onCancel={() => setPomodoroStatus('IDLE')}
            onConfirmStop={stopPomodoro}
            onResume={() => setPomodoroStatus(timeLeft > 0 ? (aiResources[17] && activeAiResourceId === aiResources[17].id ? 'FOCUS' : 'BREAK') : 'FOCUS')}
            timeLeft={timeLeft}
            activeResourceId={activeAiResourceId || undefined}
       />

       <WhiteNoiseComp 
            status={whiteNoiseStatus}
            types={WHITE_NOISE_TYPES}
            activeIndex={whiteNoiseIndex}
            isPlaying={isPlayingWhiteNoise}
            volume={localVolume}
            onPrev={() => setWhiteNoiseIndex(prev => (prev - 1 + WHITE_NOISE_TYPES.length) % WHITE_NOISE_TYPES.length)}
            onNext={() => setWhiteNoiseIndex(prev => (prev + 1) % WHITE_NOISE_TYPES.length)}
            onTogglePlay={() => setIsPlayingWhiteNoise(!isPlayingWhiteNoise)}
            onVolumeChange={setLocalVolume}
            onExit={exitWhiteNoise}
            onOpenVolume={() => setWhiteNoiseStatus('VOLUME_ADJUST')}
            onCloseVolume={() => setWhiteNoiseStatus('ACTIVE')}
       />

       <DivinationComp 
            status={divinationStatus}
            onConfirmExit={stopDivination}
            onCancelExit={() => setDivinationStatus('WAITING')}
       />

       <div className={`absolute bottom-0 left-0 right-0 h-32 bg-gradient-to-t from-black/90 via-black/50 to-transparent z-40 transition-transform duration-500 ease-out flex items-center ${isMenuOpen && pomodoroStatus === 'IDLE' && whiteNoiseStatus === 'IDLE' && divinationStatus === 'IDLE' && ranchStatus === 'IDLE' ? 'translate-y-0' : 'translate-y-full'}`}>
           <div 
             ref={menuScrollRef}
             onScroll={handleMenuScroll}
             className="w-full flex items-center overflow-x-auto no-scrollbar snap-x gap-6 py-4 px-[calc(50%-24px)]"
           >
                {menuItems.map((item, index) => {
                    const isActive = index === activeMenuIndex;
                    return (
                        <div 
                            key={item.id} 
                            onClick={item.onClick}
                            className={`flex-shrink-0 rounded-full bg-gradient-to-br ${item.color} ${item.shadow} shadow-lg flex items-center justify-center snap-center border-2 border-white/20 transform transition-all duration-300 ease-out cursor-pointer ${isActive ? 'w-16 h-16 border-white/60 scale-110 z-10 opacity-100' : 'w-12 h-12 scale-90 opacity-60'}`}
                        >
                            <div className={`${isActive ? 'text-3xl' : 'text-xl'} transition-all duration-300`}>{item.content}</div>
                        </div>
                    );
                })}
           </div>
       </div>

       <div 
         className={`absolute bottom-8 left-1/2 -translate-x-1/2 w-[70%] h-10 z-30 pointer-events-none transition-opacity duration-500 ease-in-out ${isTextBoxVisible && !isMenuOpen ? 'opacity-100' : 'opacity-0'}`}
       >
          <div className="relative w-full h-full bg-black/60 backdrop-blur-md rounded-full border border-white/20 shadow-lg flex flex-col items-center justify-center overflow-hidden">
             <div className="w-full h-full flex items-center justify-center relative px-3">
                 <div className="absolute w-full animate-vertical-scroll flex items-center justify-center">
                    <p className="text-white/95 text-[10px] font-medium text-center leading-normal drop-shadow-md font-sans tracking-wide whitespace-pre-wrap">{displayText}</p>
                 </div>
             </div>
          </div>
       </div>
     </div>
   );
});

export default ChatComp;

import React, { useState, useEffect, useRef } from 'react';
import { BadgeMode, LightColor, MenuState, Resource, ViewType } from './types';
import { initChat } from './services/geminiService';
import { 
    BATTERY_COLORS, CHEER_COLORS, AI_SLOTS, VIEW_NAMES, getThemeClasses 
} from './constants';
import { 
    SunIcon, MoonIcon, HelpIcon, BellIcon 
} from './components/Icons';
import { BatteryLevelControl, HelpModal, Wallpaper, ViewIcon } from './components/BadgeUi';
import ChatComp, { ChatCompHandle } from './components/ChatComp';
import ScreenMenu from './components/ScreenMenu';
import { BottomPanels } from './components/panels/BottomPanels';
import { AiResourcePanel } from './components/panels/AiResourcePanel';

export default function App() {
  const [mode, setMode] = useState<BadgeMode>(BadgeMode.IDLE);
  const [previousMode, setPreviousMode] = useState<BadgeMode | null>(null);
  const [lightColor, setLightColor] = useState<LightColor>(LightColor.CYAN);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [currentView, setCurrentView] = useState<ViewType>('FRONT');
  const [batteryLevel, setBatteryLevel] = useState<number>(100);
  const [isCharging, setIsCharging] = useState(false);

  // System State
  const [brightness, setBrightness] = useState(80); 
  const [volume, setVolume] = useState(60); 
  const [isPowerSaving, setIsPowerSaving] = useState(false);
  const [isScreenOff, setIsScreenOff] = useState(false); // New state for screen off (sleep) with persistence
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  // New States for Features
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);

  // App Feature States
  const [cheerColorIndex, setCheerColorIndex] = useState(0);
  const [isCheerStrobe, setIsCheerStrobe] = useState(false);
  const [isChatMenuOpen, setIsChatMenuOpen] = useState(false);

  const [uploadedText, setUploadedText] = useState("BBS 电子徽章");
  const [textSpeed, setTextSpeed] = useState<'slow' | 'medium' | 'fast'>('medium');
  const [textColor, setTextColor] = useState('#FFFFFF');
  const [textSize, setTextSize] = useState(2); 

  const [pickupData, setPickupData] = useState<number[]>(new Array(16).fill(0));

  // Resource & Wallpaper State
  const [history, setHistory] = useState<Resource[]>([]);
  const [activeResourceId, setActiveResourceId] = useState<string | null>(null);
  const [draggedResource, setDraggedResource] = useState<Resource | null>(null);

  // AI Resources State 
  const [aiResources, setAiResources] = useState<Record<number, Resource>>({});
  const [activeAiResourceId, setActiveAiResourceId] = useState<string | null>(null);
  const [isAiPanelOpen, setIsAiPanelOpen] = useState(false);
  const [pendingGiftSlotId, setPendingGiftSlotId] = useState<number | null>(null);

  // Carousel State
  const [carouselEnabled, setCarouselEnabled] = useState(false);
  const [carouselSpeed, setCarouselSpeed] = useState(3);
  const [tempSpeed, setTempSpeed] = useState(3);

  // Menu Interaction State
  const [menuState, setMenuState] = useState<MenuState>('MAIN');

  // Chat State
  const [chatStatus, setChatStatus] = useState<'IDLE' | 'LISTENING' | 'SPEAKING'>('IDLE');

  // Animation State
  const [aiPreloading, setAiPreloading] = useState(false);
  const [aiExitPreloading, setAiExitPreloading] = useState(false);
  const [isFindingDevice, setIsFindingDevice] = useState(false);

  // Swipe State
  const touchStartX = useRef<number | null>(null);

  // Long press logic
  const timerRef = useRef<number | null>(null);
  const aiAnimTimerRef = useRef<number | null>(null);
  const powerTimerRef = useRef<number | null>(null);
  const isPowerLongPress = useRef(false);
  const isPowerBtnPressed = useRef(false);

  // Chat Comp Ref
  const chatRef = useRef<ChatCompHandle>(null);

  // Audio Context for Pickup
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const dataArrayRef = useRef<Uint8Array | null>(null);
  const rafIdRef = useRef<number | null>(null);

  // Initialize Gemini
  useEffect(() => {
    initChat();
  }, []);

  // Clock
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Toast Timer
  useEffect(() => {
    if (toastMessage) {
      const timer = setTimeout(() => {
        setToastMessage(null);
      }, 2000);
      return () => clearTimeout(timer);
    }
  }, [toastMessage]);

  // Power Saving Reset on Shutdown
  useEffect(() => {
    if (mode === BadgeMode.OFF) {
      setIsPowerSaving(false);
      setIsScreenOff(false);
    }
  }, [mode]);

  // Carousel Logic
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (carouselEnabled && history.length > 0 && mode === BadgeMode.IDLE && !isScreenOff) {
      interval = setInterval(() => {
        setActiveResourceId(prevId => {
          const currentIndex = history.findIndex(r => r.id === prevId);
          const nextIndex = (currentIndex + 1) % history.length;
          return history[nextIndex].id;
        });
      }, carouselSpeed * 1000);
    }
    return () => clearInterval(interval);
  }, [carouselEnabled, history, carouselSpeed, mode, isScreenOff]);

  // Reset to first AI Resource (Default / Slot 1) or Pending Gift when entering chat
  useEffect(() => {
    if (mode === BadgeMode.CHAT_ENTERING) {
      if (pendingGiftSlotId && aiResources[pendingGiftSlotId]) {
         setActiveAiResourceId(aiResources[pendingGiftSlotId].id);
      } else if (aiResources[1]) {
        setActiveAiResourceId(aiResources[1].id);
      } else {
        setActiveAiResourceId(null);
      }
    }

    // Clear pending gift when entering CHAT mode
    if (mode === BadgeMode.CHAT && pendingGiftSlotId) {
        setPendingGiftSlotId(null);
    }

    // Reset Chat Menu when entering/exiting chat
    if (mode !== BadgeMode.CHAT) {
        setIsChatMenuOpen(false);
    }
  }, [mode, aiResources, pendingGiftSlotId]);

  // Update lights based on mode and Power Saving
  useEffect(() => {
    // Priority 1: Screen Off (unless charging logic overrides, lights usually off)
    if (isScreenOff && !isCharging) {
        setLightColor(LightColor.OFF);
        return;
    }

    // Priority 2: Power Saving
    if (isPowerSaving && mode !== BadgeMode.BOOTING && mode !== BadgeMode.SHUTTING_DOWN) {
      setLightColor(LightColor.OFF);
      return;
    }

    switch (mode) {
      case BadgeMode.OFF:
      case BadgeMode.SLEEP:
        setLightColor(LightColor.OFF);
        break;
      case BadgeMode.BOOTING:
      case BadgeMode.IDLE:
        setLightColor(LightColor.CYAN);
        break;
      case BadgeMode.SHUTTING_DOWN:
        setLightColor(LightColor.RED);
        break;
      case BadgeMode.MENU:
        setLightColor(LightColor.WHITE);
        break;
      case BadgeMode.CHAT:
        setLightColor(LightColor.WHITE); 
        break;
      case BadgeMode.CHAT_ENTERING:
      case BadgeMode.CHAT_EXITING:
         setLightColor(LightColor.WHITE);
         break;
    }
  }, [mode, isPowerSaving, isScreenOff, isCharging]);

  // Handle Boot and Shutdown Animation Timers
  useEffect(() => {
    if (mode === BadgeMode.BOOTING) {
      setIsScreenOff(false); // Ensure screen is on when booting
      const timer = setTimeout(() => {
        setMode(BadgeMode.IDLE);
        setToastMessage("系统就绪");
      }, 4000);
      return () => clearTimeout(timer);
    }
    if (mode === BadgeMode.SHUTTING_DOWN) {
      setIsScreenOff(false); // Ensure screen is on to show shutdown anim
      const timer = setTimeout(() => {
        setMode(BadgeMode.OFF);
      }, 2500);
      return () => clearTimeout(timer);
    }

    if (mode === BadgeMode.CHAT_ENTERING) {
      if (aiResources[11]?.type === 'video') return;
      const timer = setTimeout(() => setMode(BadgeMode.CHAT), 2000);
      return () => clearTimeout(timer);
    }
    if (mode === BadgeMode.CHAT_EXITING) {
      if (aiResources[12]?.type === 'video') return;
      const timer = setTimeout(() => setMode(BadgeMode.IDLE), 2000);
      return () => clearTimeout(timer);
    }
  }, [mode, aiResources]); 

  // Pickup Audio Logic
  useEffect(() => {
    if (menuState === 'PICKUP' && mode === BadgeMode.MENU && !isScreenOff) {
      const startAudio = async () => {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
          const analyser = audioCtx.createAnalyser();
          const source = audioCtx.createMediaStreamSource(stream);

          analyser.fftSize = 64;
          source.connect(analyser);

          analyserRef.current = analyser;
          audioContextRef.current = audioCtx;
          dataArrayRef.current = new Uint8Array(analyser.frequencyBinCount);

          const update = () => {
             if (!analyserRef.current || !dataArrayRef.current) return;
             analyserRef.current.getByteFrequencyData(dataArrayRef.current);
             const bars = [];
             const step = Math.floor(dataArrayRef.current.length / 16);
             for(let i=0; i<16; i++) {
               bars.push(dataArrayRef.current[i * step] / 255);
             }
             setPickupData(bars);
             rafIdRef.current = requestAnimationFrame(update);
          };
          update();

        } catch (e) {
          console.error("Audio pickup failed", e);
          setToastMessage("麦克风访问失败");
        }
      };
      startAudio();
    } else {
      if (rafIdRef.current) cancelAnimationFrame(rafIdRef.current);
      if (audioContextRef.current) audioContextRef.current.close();
      audioContextRef.current = null;
    }

    return () => {
      if (rafIdRef.current) cancelAnimationFrame(rafIdRef.current);
      if (audioContextRef.current) {
         audioContextRef.current.close().catch(() => {});
         audioContextRef.current = null;
      }
    };
  }, [menuState, mode, isScreenOff]);

  // Reset menu state when exiting menu
  useEffect(() => {
    if (mode !== BadgeMode.MENU) {
      setMenuState('MAIN');
    }
  }, [mode]);

  // --- Handlers ---

  const handlePowerDown = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    isPowerBtnPressed.current = true;
    isPowerLongPress.current = false;

    powerTimerRef.current = window.setTimeout(() => {
      if (!isPowerBtnPressed.current) return;
      isPowerLongPress.current = true;
      setIsScreenOff(false); // Force screen on for animation
      setMode(prev => {
        if (prev === BadgeMode.OFF) return BadgeMode.BOOTING;
        else if (prev !== BadgeMode.BOOTING && prev !== BadgeMode.SHUTTING_DOWN) return BadgeMode.SHUTTING_DOWN;
        return prev;
      });
      if (navigator.vibrate) navigator.vibrate(200);
    }, 2000); 
  };

  const handlePowerUp = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    if (!isPowerBtnPressed.current) return;
    isPowerBtnPressed.current = false;

    if (powerTimerRef.current) {
      clearTimeout(powerTimerRef.current);
      powerTimerRef.current = null;
    }

    if (!isPowerLongPress.current) {
       // Short Press Logic: Toggle Screen Off/On if system is active
       if (mode !== BadgeMode.OFF && mode !== BadgeMode.BOOTING && mode !== BadgeMode.SHUTTING_DOWN && mode !== BadgeMode.CHAT_ENTERING && mode !== BadgeMode.CHAT_EXITING) {
           setIsScreenOff(prev => !prev);
       }
    }
  };

  const handleFuncClick = () => {
    if (isScreenOff) return; // Ignore input if screen is off
    if ([BadgeMode.OFF, BadgeMode.SLEEP, BadgeMode.BOOTING, BadgeMode.SHUTTING_DOWN, BadgeMode.CHAT_ENTERING, BadgeMode.CHAT_EXITING].includes(mode)) return;

    if (mode === BadgeMode.CHAT) {
        if (chatRef.current && chatRef.current.handleMenuPress()) {
            return; 
        }
        setIsChatMenuOpen(prev => !prev);
        return;
    }

    if (mode === BadgeMode.MENU) {
      if (menuState !== 'MAIN') {
        setMenuState('MAIN'); 
      } else {
        if (previousMode === BadgeMode.CHAT) {
          setMode(BadgeMode.CHAT);
          setPreviousMode(null);
        } else {
          setMode(BadgeMode.IDLE);
          setPreviousMode(null);
        }
      }
    } else {
      setPreviousMode(mode);
      setMode(BadgeMode.MENU);
    }
  };

  const startAiLongPress = () => {
    if (isScreenOff) return;
    if (mode === BadgeMode.OFF || mode === BadgeMode.SLEEP || mode === BadgeMode.BOOTING || mode === BadgeMode.SHUTTING_DOWN || mode === BadgeMode.CHAT_ENTERING || mode === BadgeMode.CHAT_EXITING) return;

    if (mode === BadgeMode.CHAT) {
        aiAnimTimerRef.current = window.setTimeout(() => {
            setAiExitPreloading(true);
        }, 1000);

        timerRef.current = window.setTimeout(() => {
            setMode(BadgeMode.CHAT_EXITING);
            if (navigator.vibrate) navigator.vibrate(100);
            setAiExitPreloading(false); 
        }, 3000);
        return;
    }

    aiAnimTimerRef.current = window.setTimeout(() => {
        setAiPreloading(true);
    }, 1000);

    timerRef.current = window.setTimeout(() => {
      setMode(prev => prev === BadgeMode.CHAT ? BadgeMode.CHAT_EXITING : BadgeMode.CHAT_ENTERING);
      if (navigator.vibrate) navigator.vibrate(100);
      setAiPreloading(false); 
    }, 3000);
  };

  const endAiLongPress = () => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
    if (aiAnimTimerRef.current) {
      clearTimeout(aiAnimTimerRef.current);
      aiAnimTimerRef.current = null;
    }
    setAiPreloading(false);
    setAiExitPreloading(false);
  };

  // Menu Logic Handlers
  const togglePowerSave = () => {
    if (!isPowerSaving) {
      setIsPowerSaving(true);
      setToastMessage("进入节能模式");
      setMode(previousMode || BadgeMode.IDLE); 
    } else {
      setIsPowerSaving(false);
      setToastMessage("退出节能模式");
    }
  };

  const handleCheerClick = () => setMenuState('CHEER');
  const handleLinkClick = () => setMenuState('QRCODE');
  const handleTextClick = () => setMenuState('TEXT');
  const handlePickupClick = () => setMenuState('PICKUP');
  const handleDeleteRequest = () => setMenuState('DELETE_CONFIRM');
  const handleBrightnessClick = () => setMenuState('BRIGHTNESS');
  const handleVolumeClick = () => setMenuState('VOLUME');

  const handleGiftClick = (type: 'A_LOW' | 'A_HIGH' | 'B') => {
      const slot = type === 'B' ? 10 : 9;
      setPendingGiftSlotId(slot);
      setToastMessage(`已赠送${type === 'B' ? '专属礼物' : '礼物'}，请进入AI互动`);
  };

  const confirmDelete = () => {
    setActiveResourceId(null);
    setMenuState('MAIN');
    setToastMessage("壁纸已清除");
    setMode(BadgeMode.IDLE);
  };

  // Simulation Handlers
  const handleFindDevice = () => {
    setIsFindingDevice(true);
    if (navigator.vibrate) navigator.vibrate([500, 200, 500, 200, 500]);
    setTimeout(() => setIsFindingDevice(false), 5000);
  };

  const handleSimulateAlarm = () => {
      if (aiResources[14]) {
          setMode(BadgeMode.CHAT);
          setActiveAiResourceId(aiResources[14].id);
      } else {
          setToastMessage("模拟闹钟触发 (请先上传资源至 Slot 14)");
      }
  };

  const handleSimulateSchedule = () => {
      if (aiResources[15]) {
          setMode(BadgeMode.CHAT);
          setActiveAiResourceId(aiResources[15].id);
      } else {
          setToastMessage("模拟日程提醒 (请先上传资源至 Slot 15)");
      }
  };

  const handleSimulateMessage = () => {
      if (aiResources[13]) {
          setMode(BadgeMode.CHAT);
          setActiveAiResourceId(aiResources[13].id);
      } else {
          setToastMessage("模拟收到信息 (请先上传资源至 Slot 13)");
      }
  };

  // Helper to add resource
  const addResourceToHistory = (url: string, type: 'image' | 'video', name: string) => {
    const newResource: Resource = {
      id: Date.now().toString(),
      type,
      url,
      name
    };
    setHistory(prev => [newResource, ...prev].slice(0, 10));
    setActiveResourceId(newResource.id);
    if(mode === BadgeMode.SLEEP) setMode(BadgeMode.IDLE);
  };

  const handleImageGeneration = (url: string, name: string) => {
    addResourceToHistory(url, 'image', name);
    setMode(BadgeMode.IDLE);
    setToastMessage("图片生成成功");
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const MAX_SIZE = 100 * 1024 * 1024; // Increased to 100MB
    if (file.size > MAX_SIZE) {
      setToastMessage("资源过大，请压缩至100MB内");
      return;
    }

    const isVideo = file.type.startsWith('video/');
    const url = URL.createObjectURL(file);

    if (isVideo) {
      const tempVideo = document.createElement('video');
      tempVideo.preload = 'metadata';

      let resolved = false;
      const resolve = () => {
          if (resolved) return;
          resolved = true;
          setToastMessage("导入成功");
          addResourceToHistory(url, 'video', file.name);
      };

      // Try to load metadata to ensure validity, but don't block forever
      tempVideo.onloadedmetadata = resolve;
      tempVideo.onerror = () => {
          console.warn("Video metadata check failed, adding anyway");
          resolve();
      };

      tempVideo.src = url;

      // Fallback timeout in case browser doesn't trigger events for disconnected element
      setTimeout(resolve, 500);
    } else {
      setToastMessage("导入成功");
      addResourceToHistory(url, 'image', file.name);
    }
  };

  const handleAiFileUpload = (e: React.ChangeEvent<HTMLInputElement> | null, slotId: number, explicitFile?: File) => {
      const file = explicitFile || e?.target.files?.[0];
      if (!file) return;

      const isVideo = file.type.startsWith('video/');
      const url = URL.createObjectURL(file);

      const newResource: Resource = {
        id: Date.now().toString(),
        type: isVideo ? 'video' : 'image',
        url,
        name: file.name
      };

      setAiResources(prev => ({
        ...prev,
        [slotId]: newResource
      }));

      if (slotId === 1 && !activeAiResourceId) {
         setActiveAiResourceId(newResource.id);
      }
      setToastMessage(`AI 资源 ${slotId} 已添加`);
  };

  const handleAiResourceDelete = (slotId: number, e: React.MouseEvent) => {
     e.stopPropagation();
     const resource = aiResources[slotId];
     if (!resource) return;

     setAiResources(prev => {
        const next = { ...prev };
        delete next[slotId];
        return next;
     });

     if (activeAiResourceId === resource.id) {
         setActiveAiResourceId(null);
     }
  };

  const handleDragStart = (e: React.DragEvent, resource: Resource) => {
    setDraggedResource(resource);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragEnd = () => setDraggedResource(null);

  const handleDropDelete = (e: React.DragEvent) => {
    e.preventDefault();
    if (draggedResource) {
      setHistory(prev => prev.filter(r => r.id !== draggedResource.id));
      if (activeResourceId === draggedResource.id) setActiveResourceId(null);
      setToastMessage("资源已删除");
      setDraggedResource(null);
    }
  };

  // Swipe Handlers for Cheer/Wallpaper
  const handleTouchStart = (e: React.TouchEvent | React.MouseEvent) => {
    if ((mode !== BadgeMode.IDLE && menuState !== 'CHEER') || carouselEnabled || isScreenOff) return;
    const x = 'touches' in e ? (e as React.TouchEvent).touches[0].clientX : (e as React.MouseEvent).clientX;
    touchStartX.current = x;
  };

  const handleTouchEnd = (e: React.TouchEvent | React.MouseEvent) => {
    if (touchStartX.current === null) return;
    const x = 'changedTouches' in e ? (e as React.TouchEvent).changedTouches[0].clientX : (e as React.MouseEvent).clientX;
    const diff = touchStartX.current - x;
    touchStartX.current = null;

    if (Math.abs(diff) > 50) { 
      if (menuState === 'CHEER') {
         if (diff > 0) setCheerColorIndex(prev => (prev + 1) % CHEER_COLORS.length);
         else setCheerColorIndex(prev => (prev - 1 + CHEER_COLORS.length) % CHEER_COLORS.length);
      } else if (mode === BadgeMode.IDLE && history.length > 1) {
         if (diff > 0) setActiveResourceId(prevId => {
            const idx = history.findIndex(r => r.id === prevId);
            return history[(idx + 1) % history.length].id;
         });
         else setActiveResourceId(prevId => {
            const idx = history.findIndex(r => r.id === prevId);
            return history[(idx - 1 + history.length) % history.length].id;
         });
      }
    }
  };

  const activeResource = history.find(r => r.id === activeResourceId);
  const activeAiResource = Object.values(aiResources).find(r => r.id === activeAiResourceId);

  // --- Main Render ---

  const getLightStripStyle = () => {
    if ((mode === BadgeMode.IDLE && !isPowerSaving && !isScreenOff) || ((mode === BadgeMode.OFF || mode === BadgeMode.SLEEP || isScreenOff) && isCharging)) {
       let color = BATTERY_COLORS.HIGH;
       if (batteryLevel <= 20) color = BATTERY_COLORS.LOW;
       else if (batteryLevel <= 60) color = BATTERY_COLORS.MID;
       return { borderColor: color };
    }
    return {};
  };

  const getLightStripClass = () => {
    // If screen is off and not charging, lights are usually off
    if (isScreenOff && !isCharging) return 'opacity-0';

    if (mode === BadgeMode.MENU && menuState === 'CHEER') return 'opacity-0';
    if (isPowerSaving && mode !== BadgeMode.BOOTING && mode !== BadgeMode.SHUTTING_DOWN) return 'opacity-0';

    const chargingAnim = (isCharging && batteryLevel < 100) ? "animate-breathe-slow" : "";

    if (mode === BadgeMode.OFF || mode === BadgeMode.SLEEP) {
        if (isCharging) {
            return `absolute inset-0 rounded-full blur-md transition-all duration-700 ease-out border-[10px] opacity-80 ${chargingAnim}`;
        }
        return 'opacity-0';
    }

    let baseClass = `absolute inset-0 rounded-full blur-md transition-all duration-700 ease-out `;

    if (mode === BadgeMode.CHAT_ENTERING) return `absolute inset-0 rounded-full blur-md opacity-100 animate-spin-once bg-[conic-gradient(from_0deg,transparent_0%,white_50%,transparent_100%)]`;
    if (mode === BadgeMode.CHAT_EXITING) return `absolute inset-0 rounded-full blur-md opacity-100 animate-spin-once bg-[conic-gradient(from_0deg,transparent_0%,#01fce9_50%,transparent_100%)]`;

    if (mode === BadgeMode.CHAT) {
       if (aiExitPreloading) return 'opacity-0'; 

       if (chatStatus === 'LISTENING') return baseClass + `border-[10px] border-white opacity-100`;
       else if (chatStatus === 'SPEAKING') return baseClass + `border-[10px] border-white opacity-100 animate-breathe-fast`;
       return baseClass + `border-[10px] border-white opacity-60`;
    }

    if (mode === BadgeMode.IDLE) {
        return baseClass + `border-[10px] opacity-80 ${chargingAnim}`;
    }

    const color = lightColor.replace('border-', 'border-'); 
    return baseClass + `border-[10px] ${color} opacity-80`;
  };

  const chargingAnim = (isCharging && batteryLevel < 100) ? "animate-breathe-slow" : "";
  const batteryInfoColor = batteryLevel <= 20 ? BATTERY_COLORS.LOW : (batteryLevel <= 60 ? BATTERY_COLORS.MID : BATTERY_COLORS.HIGH);
  const themeClasses = getThemeClasses(isDarkMode);

  return (
    <div className={`min-h-screen flex items-center justify-center p-4 font-sans selection:bg-blue-500/30 overflow-hidden relative transition-colors duration-500 ${themeClasses.bg}`}>

      {/* Help Modal */}
      <HelpModal isOpen={isHelpOpen} onClose={() => setIsHelpOpen(false)} isDarkMode={isDarkMode} />

      {/* Background Ambience */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden">
        <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-gradient-to-r from-blue-900/10 to-purple-900/10 rounded-full blur-3xl transition-opacity duration-1000 ${mode === BadgeMode.OFF ? 'opacity-0' : 'opacity-100'}`}></div>
      </div>

      {/* Helper Text (Left) - Kept for quick reference */}
      <div className={`fixed top-8 left-8 text-xs space-y-2 hidden md:block font-display tracking-wide z-50 ${isDarkMode ? 'text-gray-600' : 'text-gray-400'}`}>
        <h2 className={`font-bold mb-4 border-b pb-2 ${isDarkMode ? 'text-gray-400 border-gray-800' : 'text-gray-500 border-gray-300'}`}>操作指南</h2>
        <div className="flex items-center gap-2"><span className="w-1.5 h-1.5 bg-gray-500 rounded-full"></span> 左键: 长按2秒 开/关机, 点按 亮/熄屏</div>
        <div className="flex items-center gap-2"><span className="w-1.5 h-1.5 bg-gray-500 rounded-full"></span> 右上: 长按3秒进入 AI 对话</div>
        <div className="flex items-center gap-2"><span className="w-1.5 h-1.5 bg-gray-500 rounded-full"></span> 右下: 菜单 / 返回</div>
      </div>

      {/* Top Right Controls (Theme & Help) */}
      <div className="fixed top-8 right-8 z-[55] flex items-center gap-3">
         <button 
           onClick={() => setIsDarkMode(!isDarkMode)} 
           className={`p-2 rounded-full backdrop-blur-md transition-all duration-300 border ${themeClasses.panelBgStrong} ${themeClasses.iconBase}`}
           title="切换主题"
         >
           {isDarkMode ? <SunIcon className="w-5 h-5" /> : <MoonIcon className="w-5 h-5" />}
         </button>
         <button 
           onClick={() => setIsHelpOpen(true)}
           className={`p-2 rounded-full backdrop-blur-md transition-all duration-300 border ${themeClasses.panelBgStrong} ${themeClasses.iconBase}`}
           title="使用帮助"
         >
            <HelpIcon className="w-5 h-5" />
         </button>
      </div>

      {/* View Switcher */}
      <div className={`fixed top-1/2 left-8 -translate-y-1/2 z-50 flex flex-col gap-3 backdrop-blur-md p-2 rounded-2xl border transition-colors duration-300 ${themeClasses.panelBg}`}>
         {(['LEFT', 'FRONT', 'RIGHT', 'BACK'] as ViewType[]).map((view) => (
           <button
             key={view}
             onClick={() => setCurrentView(view)}
             className={`p-2 rounded-xl transition-all duration-300 flex items-center justify-center ${currentView === view ? themeClasses.iconActive : themeClasses.iconInactive}`}
             title={VIEW_NAMES[view]}
           >
              <ViewIcon view={view} />
           </button>
         ))}
      </div>

      {/* Right Side Controls (Battery & NFC) */}
      <div className={`fixed top-1/2 right-8 -translate-y-1/2 z-50 flex flex-col gap-4 backdrop-blur-md p-3 rounded-2xl border transition-colors duration-300 ${themeClasses.panelBg}`}>

         {/* Discharging States */}
         <div className="flex flex-col gap-2">
            <span className={`text-[9px] font-bold text-center ${themeClasses.subText}`}>状态预览</span>
            {[100, 50, 20].map((level) => (
            <button
                key={level}
                onClick={() => { setBatteryLevel(level); setIsCharging(false); }}
                className={`p-2 rounded-xl transition-all duration-300 flex items-center justify-center gap-2 ${batteryLevel === level && !isCharging ? themeClasses.iconActive : themeClasses.iconInactive}`}
                title={`${level === 100 ? '高' : level === 50 ? '中' : '低'}电量`}
            >
                <BatteryLevelControl level={level} />
            </button>
            ))}
         </div>

         <div className={`h-[1px] w-full ${isDarkMode ? 'bg-gray-700/50' : 'bg-gray-300'}`}></div>

         {/* Charging States */}
         <div className="flex flex-col gap-2">
            <span className={`text-[9px] font-bold text-center ${themeClasses.subText}`}>充电模拟</span>
            {[
                { l: 100, label: '满电' },
                { l: 80, label: '高充' },
                { l: 50, label: '中充' },
                { l: 20, label: '低充' }
