                    if (aiResources[24]) {
                        if (isScreenOff) setIsScreenOff(false); // Wake up if using NFC while screen is off
                        setMode(BadgeMode.CHAT);
                        setActiveAiResourceId(aiResources[24].id);
                    }
                }}
