                       ((mode === BadgeMode.IDLE || ((mode === BadgeMode.OFF || mode === BadgeMode.SLEEP) && isCharging)) ? `opacity-40 ${chargingAnim}` : lightColor.replace('border-', 'border-') + ' opacity-40')
