                          volume={volume}
                          setVolume={setVolume}
                          handleVolumeClick={handleVolumeClick}
                          uploadedText={uploadedText}
                          textSpeed={textSpeed}
                          textColor={textColor}
                          textSize={textSize}
                          handleTextClick={handleTextClick}
                          pickupData={pickupData}
