                  <div className="w-2.5 h-2.5 rounded-full bg-gradient-to-br from-amber-300 to-amber-600 shadow-sm border border-amber-800/50"></div>
                  <div className="w-2.5 h-2.5 rounded-full bg-gradient-to-br from-amber-300 to-amber-600 shadow-sm border border-amber-800/50"></div>
                  <div className="w-2.5 h-2.5 rounded-full bg-gradient-to-br from-amber-300 to-amber-600 shadow-sm border border-amber-800/50"></div>
