    isDarkMode: boolean;
    themeClasses: any;
    onSimulateSchedule: () => void;
    onSimulateAlarm: () => void;
    onSimulateMessage: () => void;
    onGiftClick: (type: 'A_LOW' | 'A_HIGH' | 'B') => void;
