                                {res.type === 'video' && <div className="absolute inset-0 flex items-center justify-center bg-black/20"><div className="w-4 h-4 text-white opacity-80"><PlayIcon /></div></div>}
                            </div>
                            ))}
                         </div>
                    </div>
                    )}
