            coins={coins}
            floatingTexts={floatingTexts}
            selectedEntity={selectedEntity}
            onCollectCoin={collectCoin}
            onOpenDetail={openEntityDetail}
            onCloseDetail={closeRanchDetail}
            onExit={exitRanch}
       />

       <PomodoroComp 
            status={pomodoroStatus}
